window.QUESTION_BANK = {"id": "azure-ai-fundamentals", "title": "Azure AI Fundamentals", "sources": [{"id": "azure-ai-900", "name": "AI-900", "title": "Azure AI-900"}, {"id": "azure-ai-901", "name": "AI-901", "title": "Azure AI Fundamentals (AI-901)"}], "questions": [{"id": "azure-ai-900-q-001", "question": "What is the primary goal of machine learning?", "options": ["To program explicit rules for every scenario", "To enable computers to learn from data and improve without explicit programming", "To replace all human decision-making", "To create only neural network models"], "correctAnswer": 1, "explanation": "Machine learning enables computers to learn patterns from data and make predictions or decisions without being explicitly programmed for every scenario. This is fundamentally different from traditional rule-based programming where developers must code every possible outcome.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-002", "question": "Which Microsoft principle of Responsible AI focuses on ensuring AI systems treat all people fairly?", "options": ["Reliability and safety", "Fairness", "Privacy and security", "Inclusiveness"], "correctAnswer": 1, "explanation": "Fairness is the Responsible AI principle that ensures AI systems treat all people fairly and do not discriminate based on factors like gender, race, or socioeconomic status. Microsoft actively works to identify and mitigate bias in AI models to promote equitable outcomes.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-003", "question": "Anomaly detection is best described as which type of AI workload?", "options": ["Predicting future values based on historical data", "Identifying unusual patterns or outliers in data", "Understanding and generating human language", "Processing and analyzing visual information"], "correctAnswer": 1, "explanation": "Anomaly detection is an AI workload that identifies unusual patterns or outliers in data that do not conform to expected behavior. It is commonly used for fraud detection, network security monitoring, and equipment failure prediction in manufacturing.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-004", "question": "What does the Responsible AI principle of Transparency require?", "options": ["Making all AI algorithms open source", "Providing clear explanations of how AI systems make decisions", "Sharing all training data with the public", "Publishing AI system source code"], "correctAnswer": 1, "explanation": "Transparency in Responsible AI means that AI systems should be understandable and interpretable, allowing users to comprehend how decisions are made. This does not require open-sourcing algorithms or data, but rather providing meaningful explanations of AI behavior.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-005", "question": "Which AI workload would be most appropriate for forecasting product demand for the next quarter?", "options": ["Computer vision", "Natural language processing", "Prediction and forecasting", "Knowledge mining"], "correctAnswer": 2, "explanation": "Prediction and forecasting workloads use historical data to predict future values or trends. This is ideal for demand forecasting, sales prediction, and resource planning scenarios where past patterns can inform future expectations.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-006", "question": "A retail company wants to automatically identify suspicious transactions in real-time. Which AI workload should they use?", "options": ["Image classification", "Anomaly detection", "Sentiment analysis", "Speech recognition"], "correctAnswer": 1, "explanation": "Anomaly detection is specifically designed to identify unusual patterns that deviate from normal behavior. For fraud detection, the system learns normal transaction patterns and flags deviations that may indicate fraudulent activity.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-007", "question": "The Responsible AI principle of Accountability means that:", "options": ["AI systems must always be supervised by humans", "People must be responsible for decisions made by AI systems", "AI developers are the only ones responsible for AI outcomes", "Organizations cannot use AI for critical decisions"], "correctAnswer": 1, "explanation": "Accountability in Responsible AI establishes that people must remain responsible for decisions made by AI systems. Organizations must establish governance frameworks that define who is responsible for AI system outcomes and ensure appropriate oversight.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-008", "question": "Computer vision AI workloads are primarily used for:", "options": ["Processing text documents", "Analyzing and interpreting visual information from images and videos", "Predicting stock market trends", "Understanding spoken language"], "correctAnswer": 1, "explanation": "Computer vision enables AI systems to analyze and interpret visual information from images and videos. This includes tasks like object detection, facial recognition, image classification, and optical character recognition (OCR).", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-009", "question": "Which scenario best demonstrates the Responsible AI principle of Inclusiveness?", "options": ["An AI system that works equally well for users with disabilities", "An AI system that processes data faster than competitors", "An AI system that reduces operational costs", "An AI system that uses less computing power"], "correctAnswer": 0, "explanation": "Inclusiveness ensures that AI systems are designed to benefit all people regardless of ability, background, or circumstances. An AI system that accommodates users with disabilities demonstrates inclusive design principles.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-010", "question": "Natural Language Processing (NLP) AI workloads enable systems to:", "options": ["Process and analyze visual content", "Understand, interpret, and generate human language", "Control robotic movements", "Predict weather patterns"], "correctAnswer": 1, "explanation": "Natural Language Processing (NLP) enables AI systems to understand, interpret, and generate human language. This includes capabilities like text analysis, sentiment analysis, language translation, and conversational AI.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-011", "question": "A manufacturing company wants to predict when equipment will fail before it happens. Which AI workload is most appropriate?", "options": ["Image recognition", "Predictive maintenance using anomaly detection", "Speech synthesis", "Text translation"], "correctAnswer": 1, "explanation": "Predictive maintenance combines anomaly detection with forecasting to identify potential equipment failures before they occur. The system analyzes sensor data to detect patterns that typically precede failures, allowing proactive maintenance scheduling.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-012", "question": "The Privacy and Security principle in Responsible AI requires:", "options": ["All AI data to be stored on-premise only", "AI systems to be secure and respect user privacy", "AI systems to never collect personal data", "All AI decisions to be made public"], "correctAnswer": 1, "explanation": "The Privacy and Security principle requires that AI systems be secure, protect sensitive data, and respect user privacy. This includes implementing appropriate data protection measures, encryption, access controls, and compliance with privacy regulations.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-013", "question": "Knowledge mining AI workloads are used to:", "options": ["Extract valuable information from large volumes of unstructured data", "Create 3D models from 2D images", "Translate spoken language in real-time", "Generate new product designs"], "correctAnswer": 0, "explanation": "Knowledge mining extracts valuable insights from large volumes of unstructured data such as documents, images, and media files. It combines AI capabilities like NLP, computer vision, and search to discover patterns and relationships in data.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-014", "question": "Autonomous systems in AI refer to:", "options": ["Software systems that require constant human supervision", "Systems capable of performing tasks without human intervention", "Cloud-based data storage systems", "Network security protocols"], "correctAnswer": 1, "explanation": "Autonomous systems are AI-powered systems capable of performing tasks and making decisions without direct human intervention. Examples include self-driving vehicles, autonomous drones, and automated industrial robots.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-015", "question": "A bank notices their loan approval AI system consistently rejects applications from a specific demographic group. Which Responsible AI principle is being violated?", "options": ["Reliability and safety", "Fairness", "Transparency", "Accountability"], "correctAnswer": 1, "explanation": "This scenario demonstrates a violation of the Fairness principle, where the AI system is exhibiting discriminatory behavior against a specific demographic group. Fairness requires that AI systems treat all people equitably and not perpetuate biases.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-016", "question": "Which of the following is an example of generative AI?", "options": ["A system that classifies emails as spam or not spam", "A system that creates new images based on text descriptions", "A system that identifies objects in photographs", "A system that predicts tomorrow's temperature"], "correctAnswer": 1, "explanation": "Generative AI creates new content such as text, images, audio, or code based on learned patterns. A system that generates images from text descriptions is a classic example of generative AI, using models like DALL-E or Stable Diffusion.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-017", "question": "Reliability and Safety in Responsible AI means:", "options": ["AI systems should never fail under any circumstances", "AI systems should perform consistently and safely under expected conditions", "AI systems should only be used in non-critical applications", "AI systems should have manual override options only"], "correctAnswer": 1, "explanation": "Reliability and Safety requires that AI systems perform consistently and safely under expected conditions, with appropriate safeguards for edge cases. This includes thorough testing, validation, and monitoring to ensure predictable behavior.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-018", "question": "A company wants to automatically categorize customer support tickets by urgency. Which AI workload is most suitable?", "options": ["Computer vision", "Natural language processing", "Anomaly detection", "Autonomous systems"], "correctAnswer": 1, "explanation": "Natural Language Processing (NLP) is ideal for analyzing and categorizing text-based content like support tickets. NLP can understand ticket content, extract intent and sentiment, and classify tickets by urgency or topic automatically.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-019", "question": "Which scenario demonstrates the use of computer vision in healthcare?", "options": ["Scheduling patient appointments automatically", "Analyzing medical images to detect tumors", "Transcribing doctor-patient conversations", "Managing electronic health records"], "correctAnswer": 1, "explanation": "Analyzing medical images to detect tumors is a computer vision application. AI systems can examine X-rays, MRIs, and CT scans to identify anomalies, assisting radiologists in diagnosis and potentially catching issues earlier.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-020", "question": "What is a key consideration when implementing AI systems for high-stakes decisions like medical diagnosis?", "options": ["AI systems should replace human judgment entirely", "Human oversight and the ability to explain AI decisions are essential", "Only simple algorithms should be used", "AI systems should only provide binary yes/no answers"], "correctAnswer": 1, "explanation": "For high-stakes decisions, human oversight and explainability are essential. The Transparency principle requires that AI decisions can be understood and reviewed by humans, and Accountability ensures humans remain responsible for outcomes.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-021", "question": "A chatbot that can understand customer questions and provide relevant responses uses which type of AI workload?", "options": ["Computer vision", "Natural language processing", "Time series forecasting", "Reinforcement learning only"], "correctAnswer": 1, "explanation": "Conversational AI and chatbots rely on Natural Language Processing to understand user input, determine intent, and generate appropriate responses. This involves multiple NLP capabilities including intent recognition, entity extraction, and response generation.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-022", "question": "Which approach helps identify potential bias in AI training data?", "options": ["Using more computing power", "Analyzing data distributions across different demographic groups", "Reducing the size of the dataset", "Encrypting all training data"], "correctAnswer": 1, "explanation": "Analyzing data distributions across demographic groups helps identify potential bias in training data. If certain groups are underrepresented or represented with skewed patterns, the resulting model may exhibit unfair behavior toward those groups.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-023", "question": "Generative AI models like GPT are primarily used for:", "options": ["Sorting numerical data", "Creating new content including text, code, and images", "Optimizing database queries", "Monitoring network traffic"], "correctAnswer": 1, "explanation": "Generative AI models like GPT create new content by learning patterns from training data. They can generate human-like text, write code, create images, compose music, and produce various other types of creative content based on prompts.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-generative-ai-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-024", "question": "A retail company uses AI to analyze social media posts about their products. This is an example of:", "options": ["Computer vision", "Sentiment analysis using NLP", "Anomaly detection", "Predictive maintenance"], "correctAnswer": 1, "explanation": "Sentiment analysis is an NLP technique that determines the emotional tone behind text. By analyzing social media posts, companies can understand public opinion, track brand perception, and identify customer satisfaction trends.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-025", "question": "What is the primary risk of deploying an AI system without proper Responsible AI governance?", "options": ["The system will be slower than competitors", "Potential for harmful outcomes including bias, privacy violations, and lack of accountability", "The system will require more cloud storage", "The system will have higher latency"], "correctAnswer": 1, "explanation": "Without proper Responsible AI governance, organizations risk deploying systems that may cause harm through biased decisions, privacy violations, security vulnerabilities, and unclear accountability. These risks can damage users, reputation, and legal standing.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-026", "question": "In supervised learning, what is the relationship between features and labels?", "options": ["Features and labels are the same thing", "Features are input variables used to predict the label (output)", "Labels are used to create features", "There is no relationship between features and labels"], "correctAnswer": 1, "explanation": "In supervised learning, features are the input variables (independent variables) that the model uses to make predictions, while the label is the output variable (dependent variable) that the model learns to predict based on the features.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-027", "question": "What distinguishes unsupervised learning from supervised learning?", "options": ["Unsupervised learning requires more computing power", "Unsupervised learning works with unlabeled data to find patterns", "Unsupervised learning is always more accurate", "Unsupervised learning can only work with images"], "correctAnswer": 1, "explanation": "Unsupervised learning works with unlabeled data, finding hidden patterns and structures without predefined target outputs. Common tasks include clustering similar data points and dimensionality reduction.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-028", "question": "Regression is a machine learning technique used for:", "options": ["Classifying data into categories", "Predicting continuous numerical values", "Grouping similar data points", "Reducing data dimensionality"], "correctAnswer": 1, "explanation": "Regression is used to predict continuous numerical values such as prices, temperatures, or sales figures. It models the relationship between input features and a continuous output variable.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-029", "question": "Classification algorithms are best suited for which type of problem?", "options": ["Predicting house prices", "Determining whether an email is spam or not spam", "Forecasting stock prices", "Estimating temperature trends"], "correctAnswer": 1, "explanation": "Classification is used to predict discrete categories or classes. Determining whether an email is spam or not spam is a binary classification problem where the output is a discrete category rather than a continuous value.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-030", "question": "Clustering is an example of which type of machine learning?", "options": ["Supervised learning", "Unsupervised learning", "Reinforcement learning", "Semi-supervised learning"], "correctAnswer": 1, "explanation": "Clustering is an unsupervised learning technique that groups similar data points together without predefined labels. The algorithm discovers natural groupings in the data based on feature similarities.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-031", "question": "In reinforcement learning, what does an agent learn to do?", "options": ["Memorize all training data", "Take actions in an environment to maximize rewards", "Cluster similar data points", "Reduce the dimensionality of data"], "correctAnswer": 1, "explanation": "In reinforcement learning, an agent learns to make decisions by taking actions in an environment to maximize cumulative rewards. The agent learns through trial and error, receiving feedback in the form of rewards or penalties.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-032", "question": "Deep learning differs from traditional machine learning primarily in that:", "options": ["Deep learning uses neural networks with multiple layers", "Deep learning requires less data", "Deep learning is always faster to train", "Deep learning only works with images"], "correctAnswer": 0, "explanation": "Deep learning uses artificial neural networks with multiple hidden layers (hence \"deep\") to learn hierarchical representations of data. These deep neural networks can automatically learn complex features from raw data.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-033", "question": "A model that predicts whether a customer will churn (leave) or stay is an example of:", "options": ["Regression", "Binary classification", "Clustering", "Dimensionality reduction"], "correctAnswer": 1, "explanation": "Predicting whether a customer will churn (yes/no) is a binary classification problem. The output has two possible classes, making it a binary rather than multi-class classification scenario.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-034", "question": "What is the purpose of splitting data into training and testing sets?", "options": ["To reduce the amount of data processed", "To evaluate model performance on unseen data", "To increase training speed", "To simplify the model architecture"], "correctAnswer": 1, "explanation": "Splitting data into training and testing sets allows evaluation of model performance on data it has not seen during training. This helps estimate how well the model will generalize to new, real-world data.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-035", "question": "Overfitting occurs when a machine learning model:", "options": ["Is too simple to capture patterns in data", "Memorizes training data but performs poorly on new data", "Takes too long to train", "Uses too little computational power"], "correctAnswer": 1, "explanation": "Overfitting occurs when a model learns the training data too well, including its noise and outliers, resulting in poor generalization to new data. The model essentially memorizes rather than learns generalizable patterns.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-036", "question": "K-means is an algorithm commonly used for:", "options": ["Predicting continuous values", "Clustering data into K groups", "Classifying text sentiment", "Reducing image resolution"], "correctAnswer": 1, "explanation": "K-means is a clustering algorithm that partitions data into K distinct groups based on feature similarity. It iteratively assigns data points to clusters and updates cluster centers until convergence.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-037", "question": "A recommendation system that suggests products based on similar users' preferences uses:", "options": ["Supervised classification", "Collaborative filtering", "Linear regression", "Dimensionality reduction"], "correctAnswer": 1, "explanation": "Collaborative filtering is a technique used in recommendation systems that makes predictions based on the collective behavior of similar users. It assumes that users who agreed in the past will agree in the future.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-038", "question": "In a neural network, what is the role of the activation function?", "options": ["To store training data", "To introduce non-linearity and determine neuron output", "To reduce the number of layers", "To encrypt model weights"], "correctAnswer": 1, "explanation": "Activation functions introduce non-linearity into neural networks, allowing them to learn complex patterns. They determine whether a neuron should be activated based on the weighted sum of inputs, producing the neuron's output.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-039", "question": "Feature engineering is the process of:", "options": ["Creating new hardware for ML training", "Selecting and transforming variables for use in models", "Visualizing model results", "Deploying models to production"], "correctAnswer": 1, "explanation": "Feature engineering involves selecting, modifying, or creating variables (features) from raw data to improve model performance. This includes techniques like normalization, encoding categorical variables, and creating derived features.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-040", "question": "Which metric would be most appropriate for evaluating a binary classification model?", "options": ["Mean squared error", "Accuracy, precision, and recall", "R-squared", "Silhouette score"], "correctAnswer": 1, "explanation": "For binary classification, metrics like accuracy, precision, and recall are appropriate. These measure different aspects of classification performance, including overall correctness, ability to avoid false positives, and ability to find all positive instances.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-041", "question": "Cross-validation is used to:", "options": ["Speed up model training", "Assess model generalization using multiple train-test splits", "Reduce the number of features", "Encrypt the training data"], "correctAnswer": 1, "explanation": "Cross-validation assesses model generalization by partitioning data into multiple subsets, training on some and validating on others in rotation. This provides a more robust estimate of model performance than a single train-test split.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-042", "question": "A model that predicts housing prices based on features like square footage and location is using:", "options": ["Classification", "Regression", "Clustering", "Association rules"], "correctAnswer": 1, "explanation": "Predicting housing prices is a regression problem because the output is a continuous numerical value. The model learns the relationship between input features (square footage, location) and the continuous target variable (price).", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-043", "question": "What is the primary advantage of using ensemble methods like Random Forest?", "options": ["They always train faster than single models", "They combine multiple models to improve accuracy and robustness", "They require less training data", "They are easier to interpret"], "correctAnswer": 1, "explanation": "Ensemble methods like Random Forest combine predictions from multiple models to improve overall performance. By aggregating diverse models, they often achieve better accuracy and are less prone to overfitting than single models.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-044", "question": "In the machine learning lifecycle, what occurs during the deployment phase?", "options": ["Collecting training data", "Making the trained model available for use in production", "Cleaning and preprocessing data", "Selecting appropriate algorithms"], "correctAnswer": 1, "explanation": "Deployment involves making a trained model available for use in production environments where it can process real-world data and provide predictions. This includes setting up APIs, scaling infrastructure, and monitoring performance.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-045", "question": "Hyperparameter tuning is the process of:", "options": ["Selecting the best features for a model", "Optimizing model configuration parameters", "Adjusting the learning rate during training only", "Cleaning the training data"], "correctAnswer": 1, "explanation": "Hyperparameter tuning involves optimizing the configuration parameters that govern the training process (like learning rate, number of layers, or regularization strength) to find the best model performance.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-046", "question": "A self-driving car learning to navigate through trial and error represents which type of machine learning?", "options": ["Supervised learning", "Unsupervised learning", "Reinforcement learning", "Transfer learning"], "correctAnswer": 2, "explanation": "A self-driving car learning through trial and error is an example of reinforcement learning. The agent (car) learns optimal actions by receiving rewards or penalties based on its performance in the environment.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-047", "question": "What does normalization of data typically involve?", "options": ["Adding more data samples", "Scaling features to a standard range like 0 to 1", "Removing duplicate records", "Encrypting sensitive values"], "correctAnswer": 1, "explanation": "Normalization scales features to a standard range (typically 0-1 or -1 to 1), ensuring that features with different scales contribute equally to the model. This improves training stability and convergence speed.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-048", "question": "Which machine learning technique is most appropriate for segmenting customers into distinct groups based on purchasing behavior?", "options": ["Linear regression", "Clustering", "Binary classification", "Time series forecasting"], "correctAnswer": 1, "explanation": "Clustering is ideal for customer segmentation as it groups similar customers together without predefined categories. The algorithm discovers natural segments based on purchasing patterns and behavioral similarities.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-049", "question": "What is the primary purpose of a loss function in machine learning?", "options": ["To store model parameters", "To measure how well the model predictions match actual values", "To increase the model size", "To encrypt the training data"], "correctAnswer": 1, "explanation": "A loss function measures the difference between model predictions and actual target values, quantifying model error. During training, the model adjusts its parameters to minimize this loss, improving prediction accuracy.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-050", "question": "In deep learning, what are convolutional neural networks (CNNs) primarily used for?", "options": ["Processing sequential data like time series", "Analyzing visual and spatial data like images", "Translating between languages", "Sorting tabular data"], "correctAnswer": 1, "explanation": "Convolutional Neural Networks (CNNs) are designed for processing grid-like data such as images. They use convolution operations to detect local patterns and features, making them highly effective for computer vision tasks.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-051", "question": "What is Azure Machine Learning?", "options": ["A Python library for data visualization", "A cloud service for building, training, and deploying ML models", "A hardware device for AI processing", "A database for storing AI training data"], "correctAnswer": 1, "explanation": "Azure Machine Learning is a cloud-based service that provides tools and frameworks for data scientists and developers to build, train, and deploy machine learning models at scale. It includes features like automated ML, visual drag-and-drop designer, and managed compute resources.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-052", "question": "What is the purpose of an Azure Machine Learning workspace?", "options": ["To store only trained ML models", "To provide a centralized place for all ML resources and experiments", "To execute Python code locally", "To monitor Azure subscription billing"], "correctAnswer": 1, "explanation": "An Azure Machine Learning workspace is the top-level resource that provides a centralized place to work with all the artifacts you create when using Azure Machine Learning. It stores experiments, compute targets, models, pipelines, and datasets.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-053", "question": "What is Automated Machine Learning (AutoML) in Azure?", "options": ["A manual process for feature engineering", "A service that automatically trains and tunes multiple ML models", "A tool for labeling data manually", "A service for deploying VMs automatically"], "correctAnswer": 1, "explanation": "Automated Machine Learning (AutoML) in Azure automatically trains and tunes multiple machine learning models using your data. It iterates through different algorithms and hyperparameters to find the best model for your specific dataset and prediction task.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-054", "question": "What type of machine learning task is predicting house prices?", "options": ["Classification", "Regression", "Clustering", "Anomaly detection"], "correctAnswer": 1, "explanation": "Predicting house prices is a regression task because it involves predicting a continuous numerical value. Classification predicts discrete categories, clustering groups similar items, and anomaly detection identifies outliers.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-055", "question": "What type of machine learning task is identifying spam emails?", "options": ["Classification", "Regression", "Clustering", "Forecasting"], "correctAnswer": 0, "explanation": "Identifying spam emails is a classification task because it involves predicting discrete categories (spam or not spam). Classification algorithms categorize input data into predefined classes.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-056", "question": "What is the Azure ML Designer?", "options": ["A code editor for Python scripts", "A drag-and-drop interface for building ML pipelines", "A tool for designing database schemas", "A dashboard for monitoring Azure costs"], "correctAnswer": 1, "explanation": "Azure ML Designer is a drag-and-drop interface that allows you to build machine learning pipelines visually. You can connect datasets and modules to create ML workflows without writing code.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-057", "question": "What is a compute instance in Azure Machine Learning?", "options": ["A virtual machine for development and experimentation", "A storage account for model artifacts", "A database for training data", "A networking component for security"], "correctAnswer": 0, "explanation": "A compute instance in Azure Machine Learning is a managed cloud-based workstation (virtual machine) used for development and experimentation. It provides a pre-configured environment for data scientists to write code, run notebooks, and train models.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-058", "question": "What is a compute cluster in Azure Machine Learning?", "options": ["A single virtual machine for development", "A scalable cluster of VMs for training models at scale", "A storage solution for datasets", "A network security group"], "correctAnswer": 1, "explanation": "A compute cluster in Azure Machine Learning is a managed cluster of virtual machines that can scale up and down automatically. It is used for training machine learning models at scale and supports distributed training across multiple nodes.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-059", "question": "What is the purpose of feature engineering in machine learning?", "options": ["To deploy models to production", "To create new features or transform existing ones to improve model performance", "To monitor model performance in real-time", "To label training data manually"], "correctAnswer": 1, "explanation": "Feature engineering is the process of creating new features or transforming existing features to improve machine learning model performance. It involves selecting, modifying, or creating variables that help the model learn patterns more effectively.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-060", "question": "What is the difference between training data and test data?", "options": ["Training data is used to train the model; test data is used to evaluate model performance", "Training data is newer than test data", "Test data is used for feature engineering only", "There is no difference between them"], "correctAnswer": 0, "explanation": "Training data is used to train the machine learning model, allowing it to learn patterns. Test data is held separate and used to evaluate how well the model generalizes to unseen data, providing an unbiased assessment of model performance.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-061", "question": "What is model overfitting?", "options": ["When a model performs well on training data but poorly on new data", "When a model is too simple to capture patterns", "When training takes too long", "When a model uses too little data"], "correctAnswer": 0, "explanation": "Overfitting occurs when a machine learning model learns the training data too well, including its noise and outliers, resulting in poor generalization to new, unseen data. The model essentially memorizes the training data rather than learning generalizable patterns.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-062", "question": "What is a real-time inference endpoint in Azure Machine Learning?", "options": ["A storage location for training datasets", "A deployed model service that provides immediate predictions for single requests", "A compute resource for batch processing", "A tool for data visualization"], "correctAnswer": 1, "explanation": "A real-time inference endpoint in Azure Machine Learning is a deployed web service that provides immediate predictions for individual requests. It is designed for low-latency scenarios where quick responses are needed, such as web applications or mobile apps.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-063", "question": "What is batch inference in Azure Machine Learning?", "options": ["Training a model on small batches of data", "Processing large volumes of data asynchronously to generate predictions", "Validating training data in batches", "Deploying models one at a time"], "correctAnswer": 1, "explanation": "Batch inference (or batch scoring) in Azure Machine Learning is the process of using a trained model to generate predictions on large volumes of data asynchronously. It is ideal for scenarios that do not require immediate responses, such as nightly report generation.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-064", "question": "What is the purpose of model monitoring in Azure Machine Learning?", "options": ["To track training data changes over time", "To detect performance degradation and data drift in deployed models", "To monitor Azure subscription costs only", "To manage user access permissions"], "correctAnswer": 1, "explanation": "Model monitoring in Azure Machine Learning helps track the performance of deployed models over time and detect issues like data drift (when the input data distribution changes) or model degradation. This enables proactive model retraining and maintenance.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-065", "question": "What is data drift in machine learning?", "options": ["When training data is accidentally deleted", "When the statistical properties of input data change over time", "When models are deployed to different regions", "When compute resources are scaled automatically"], "correctAnswer": 1, "explanation": "Data drift (also called feature drift or covariate shift) occurs when the statistical properties of the input data change over time compared to the data the model was trained on. This can cause model performance to degrade, requiring model retraining.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-066", "question": "A retail company wants to predict next month's sales based on historical data. Which Azure ML task type should they use?", "options": ["Classification", "Regression", "Forecasting", "Clustering"], "correctAnswer": 2, "explanation": "Forecasting is the appropriate task type for predicting future values based on time-series historical data. While regression predicts continuous values, forecasting specifically handles time-dependent patterns and seasonality in data, making it ideal for sales predictions.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts", "azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-067", "question": "A healthcare organization needs to classify X-ray images as normal or abnormal. Which Azure ML capability is most suitable?", "options": ["Automated ML for computer vision", "Azure ML Designer for text analytics", "Batch inference for tabular data", "Azure ML pipelines for data ingestion"], "correctAnswer": 0, "explanation": "Automated ML for computer vision is the most suitable capability for image classification tasks like analyzing X-rays. Azure AutoML supports image classification, object detection, and image segmentation, making it ideal for medical imaging scenarios.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques", "azure-ml-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-068", "question": "A data scientist wants to experiment with different algorithms without writing code. Which Azure ML tool should they use?", "options": ["Azure ML SDK for Python", "Azure ML Designer", "Azure DevOps", "Azure Data Factory"], "correctAnswer": 1, "explanation": "Azure ML Designer provides a visual, drag-and-drop interface for building machine learning pipelines without writing code. It allows data scientists to experiment with different algorithms, preprocessing steps, and model configurations visually.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-069", "question": "A company needs to process millions of customer records nightly to generate risk scores. Which deployment approach should they use?", "options": ["Real-time inference endpoint", "Batch inference pipeline", "Compute instance for interactive scoring", "Azure ML Designer web service"], "correctAnswer": 1, "explanation": "Batch inference is the appropriate approach for processing large volumes of data asynchronously. It is designed for scenarios like nightly processing jobs where immediate responses are not required, and large datasets need to be scored efficiently.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-070", "question": "An e-commerce company wants to provide instant product recommendations as customers browse. Which deployment option is best?", "options": ["Batch inference scheduled hourly", "Real-time inference endpoint", "Azure ML compute cluster for training", "Azure ML Designer offline scoring"], "correctAnswer": 1, "explanation": "A real-time inference endpoint is the best choice for providing instant product recommendations. It offers low-latency predictions for individual requests, making it ideal for interactive scenarios where users need immediate responses during browsing.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-071", "question": "What is the primary benefit of using Automated ML for a classification problem?", "options": ["It eliminates the need for any data preparation", "It automatically tries multiple algorithms and hyperparameters to find the best model", "It guarantees 100% accuracy on test data", "It requires no compute resources"], "correctAnswer": 1, "explanation": "Automated ML automatically iterates through multiple machine learning algorithms and hyperparameter combinations to find the best-performing model for your data. It saves time and expertise by automating the model selection and tuning process.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-072", "question": "A financial institution notices their loan default prediction model is performing poorly on recent data. What might be the issue?", "options": ["The model needs more compute resources", "Data drift has occurred due to changing economic conditions", "The training data was too large", "The model was trained for too many epochs"], "correctAnswer": 1, "explanation": "Poor performance on recent data often indicates data drift, where the statistical properties of the input data have changed over time. In this case, changing economic conditions may have altered loan applicant profiles, making the original model less accurate.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-073", "question": "What is the purpose of splitting data into training, validation, and test sets?", "options": ["To reduce the total amount of data used", "To train on one subset, tune hyperparameters on another, and evaluate final performance on unseen data", "To create backup copies of the dataset", "To comply with data privacy regulations"], "correctAnswer": 1, "explanation": "The three-way split allows you to train the model on the training set, tune hyperparameters and select models using the validation set, and then get an unbiased final performance estimate on the completely unseen test set. This prevents overfitting to the test data.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-074", "question": "Which metric would be most appropriate for evaluating a fraud detection model?", "options": ["Mean Absolute Error (MAE)", "R-squared", "Precision and Recall", "Mean Squared Error (MSE)"], "correctAnswer": 2, "explanation": "Precision and Recall are the most appropriate metrics for fraud detection, which is an imbalanced classification problem. Precision measures how many predicted frauds are actual frauds, while recall measures how many actual frauds are correctly identified. MAE, MSE, and R-squared are regression metrics.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-075", "question": "A data scientist is preparing data for a machine learning model. Which preprocessing step is typically required for numerical features?", "options": ["One-hot encoding", "Normalization or standardization", "Tokenization", "Text vectorization"], "correctAnswer": 1, "explanation": "Normalization or standardization is typically required for numerical features to ensure all features are on a similar scale. This helps many machine learning algorithms converge faster and perform better. One-hot encoding is for categorical data, while tokenization and text vectorization are for text data.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-076", "question": "What is the difference between a compute instance and a compute cluster in Azure ML?", "options": ["Compute instances are for training; compute clusters are for storage", "Compute instances are single VMs for development; compute clusters are scalable multi-node resources for training at scale", "Compute instances are free; compute clusters are paid", "Compute instances run Windows; compute clusters run Linux"], "correctAnswer": 1, "explanation": "Compute instances are single virtual machines designed for interactive development and experimentation. Compute clusters are scalable, multi-node resources that automatically scale up and down and are designed for training models at scale, including distributed training.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-077", "question": "A company wants to categorize customer support tickets by urgency (High, Medium, Low). What type of machine learning problem is this?", "options": ["Regression", "Binary classification", "Multiclass classification", "Clustering"], "correctAnswer": 2, "explanation": "This is a multiclass classification problem because there are three distinct categories (High, Medium, Low) to predict. Binary classification only handles two classes, regression predicts continuous values, and clustering is unsupervised without predefined labels.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-078", "question": "What is cross-validation in machine learning?", "options": ["Validating data across different cloud regions", "A technique that splits data into multiple folds for more robust model evaluation", "Checking if the model works on different operating systems", "Validating data formats before ingestion"], "correctAnswer": 1, "explanation": "Cross-validation is a technique where the dataset is divided into multiple folds. The model is trained on different subsets and validated on the remaining data, rotating through all folds. This provides a more robust estimate of model performance, especially with limited data.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-079", "question": "A manufacturing company wants to predict when equipment will fail based on sensor data. What type of machine learning approach is most appropriate?", "options": ["Image classification", "Time-series forecasting or anomaly detection", "Text sentiment analysis", "Recommendation system"], "correctAnswer": 1, "explanation": "Predictive maintenance using sensor data typically employs time-series forecasting or anomaly detection. These approaches can identify patterns that precede failures or detect anomalous readings that indicate impending equipment problems.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-080", "question": "What is the purpose of a validation dataset in machine learning?", "options": ["To train the initial model", "To tune hyperparameters and select the best model without touching the test set", "To store backup copies of training data", "To validate data formats are correct"], "correctAnswer": 1, "explanation": "The validation dataset is used during the training process to tune hyperparameters and compare different models. It helps prevent overfitting to the test set by providing an independent dataset for model selection before final evaluation on the test set.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-081", "question": "Which AutoML task type should be used to predict customer churn (will leave/stay)?", "options": ["Regression", "Binary classification", "Multiclass classification", "Forecasting"], "correctAnswer": 1, "explanation": "Customer churn prediction is a binary classification problem because there are two possible outcomes: the customer will either churn (leave) or not churn (stay). Binary classification is used when predicting between exactly two classes.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-082", "question": "What is a pipeline in Azure Machine Learning?", "options": ["A physical network connection between data centers", "A workflow that orchestrates multiple machine learning steps such as data preparation, training, and deployment", "A storage container for model artifacts", "A single training script execution"], "correctAnswer": 1, "explanation": "An Azure ML pipeline is a workflow that orchestrates multiple machine learning steps, such as data preparation, feature engineering, model training, evaluation, and deployment. Pipelines enable reusable, reproducible, and automated ML workflows.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-083", "question": "A company has imbalanced data where only 1% of transactions are fraudulent. What technique can help address this?", "options": ["Using only accuracy as the evaluation metric", "Applying class balancing techniques like SMOTE or adjusting class weights", "Removing all non-fraudulent transactions", "Using regression instead of classification"], "correctAnswer": 1, "explanation": "For imbalanced datasets, techniques like SMOTE (Synthetic Minority Over-sampling Technique) or adjusting class weights help the model learn from the minority class (fraud cases) more effectively. Using accuracy alone is misleading with imbalanced data.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-084", "question": "What is the purpose of registering a model in Azure Machine Learning?", "options": ["To delete old model versions", "To version, store, and manage trained models for deployment and tracking", "To convert models to different programming languages", "To compress model file sizes"], "correctAnswer": 1, "explanation": "Model registration in Azure ML allows you to version, store, and manage trained models in a central repository. Registered models can be tracked, compared, and deployed to various endpoints. This enables model governance and reproducibility.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-085", "question": "What is an experiment in Azure Machine Learning?", "options": ["A failed model training attempt", "A container for multiple related training runs and their outputs", "A production deployment of a model", "A type of compute resource"], "correctAnswer": 1, "explanation": "An experiment in Azure ML is a container for multiple related training runs. It helps organize and track different iterations of model training, including parameters, metrics, and outputs, making it easier to compare approaches and reproduce results.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-086", "question": "Which metric should be used to evaluate a regression model that predicts house prices?", "options": ["Accuracy", "Precision", "Root Mean Squared Error (RMSE)", "F1 Score"], "correctAnswer": 2, "explanation": "Root Mean Squared Error (RMSE) is appropriate for evaluating regression models. It measures the average magnitude of prediction errors, penalizing larger errors more heavily. Accuracy, precision, and F1 score are classification metrics, not suitable for continuous value prediction.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-087", "question": "A data team wants to automatically retrain their model weekly with new data. Which Azure ML feature supports this?", "options": ["Compute instances only", "Azure ML pipelines with scheduling", "Real-time endpoints", "Model registration"], "correctAnswer": 1, "explanation": "Azure ML pipelines with scheduling enable automated, recurring execution of machine learning workflows. This allows teams to set up automated retraining pipelines that run on a schedule (e.g., weekly) to incorporate new data and maintain model performance.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-088", "question": "What is the primary purpose of feature selection in machine learning?", "options": ["To select the best machine learning algorithm", "To identify and keep only the most relevant input variables for model training", "To choose the optimal compute resources", "To select test data samples"], "correctAnswer": 1, "explanation": "Feature selection is the process of identifying and selecting a subset of the most relevant input features for model training. It helps reduce overfitting, improve model performance, reduce training time, and make models more interpretable by removing irrelevant or redundant features.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-089", "question": "A retail company wants to group customers with similar purchasing behavior without predefined categories. Which technique should they use?", "options": ["Supervised classification", "Clustering", "Regression analysis", "Time-series forecasting"], "correctAnswer": 1, "explanation": "Clustering is an unsupervised learning technique that groups similar data points together without predefined labels. It is ideal for customer segmentation where natural groupings in purchasing behavior need to be discovered rather than predicted from known categories.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-090", "question": "What is hyperparameter tuning in machine learning?", "options": ["Adjusting the parameters learned during training", "Optimizing the configuration settings that control the training process", "Tuning the database connection parameters", "Adjusting network bandwidth for training"], "correctAnswer": 1, "explanation": "Hyperparameter tuning (or hyperparameter optimization) is the process of finding the optimal configuration settings that control the learning process, such as learning rate, number of trees in a random forest, or regularization strength. These are different from model parameters, which are learned during training.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-091", "question": "A data science team has deployed a model to production and notices performance degrading over three months while data distribution appears stable. What is the most likely cause?", "options": ["Concept drift - the relationship between inputs and outputs has changed", "Data drift - the input data distribution has changed", "Insufficient training epochs", "The model is underfitting"], "correctAnswer": 0, "explanation": "When model performance degrades despite stable input data distribution, concept drift is likely occurring. Concept drift happens when the underlying relationship between input features and the target variable changes over time. This is different from data drift, which involves changes in input feature distributions.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-092", "question": "An insurance company is building a claims fraud detection system. They have 100,000 claims with only 500 confirmed fraud cases. Which approach combination is most appropriate?", "options": ["Use accuracy as the primary metric and standard cross-validation", "Use precision/recall/F1 with stratified sampling and class weighting or SMOTE", "Treat it as a regression problem predicting fraud amount", "Remove majority class samples to create a balanced dataset of 1,000 records"], "correctAnswer": 1, "explanation": "For severely imbalanced data (0.5% fraud rate), precision, recall, and F1 score are more appropriate metrics than accuracy. Stratified sampling ensures both classes are represented in train/test splits, and class weighting or SMOTE helps the model learn from the minority class without discarding valuable majority class data.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-093", "question": "A manufacturing company has sensor data from 1,000 machines collected every minute for a year. They want to predict failures 24 hours in advance. What ML approach is most suitable?", "options": ["Simple binary classification on individual sensor readings", "Time-series forecasting or survival analysis with feature engineering for temporal patterns", "Image classification of sensor dashboards", "Clustering machines by location only"], "correctAnswer": 1, "explanation": "Predicting equipment failures with time-series sensor data requires capturing temporal patterns and trends. Time-series forecasting or survival analysis with appropriate feature engineering (rolling averages, time-based features, degradation trends) is most suitable. Simple classification on individual readings would miss the temporal degradation patterns.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques", "azure-ml-core-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-094", "question": "A data scientist is comparing two models: Model A has 95% accuracy on training data but 78% on test data. Model B has 85% accuracy on both. Which statement is correct?", "options": ["Model A is better because it has higher training accuracy", "Model B is likely better because it generalizes better to unseen data", "Both models are equivalent in performance", "Neither model is usable"], "correctAnswer": 1, "explanation": "Model A is overfitting (large gap between training and test performance), while Model B generalizes better with consistent performance on both datasets. Better generalization to unseen data is more important than high training accuracy, making Model B the preferred choice for production deployment.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts", "azure-ml-techniques"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-095", "question": "In Azure ML Designer, a data scientist connects a \"Clean Missing Data\" module before the \"Split Data\" module. What is the primary reason for this sequence?", "options": ["Missing data must be cleaned before splitting to prevent data leakage", "The Split Data module cannot handle missing values", "It is required by Azure ML Designer syntax", "Missing data cleaning is only possible on training data"], "correctAnswer": 0, "explanation": "Data preprocessing like cleaning missing values should be done before splitting data to ensure consistent handling across all subsets and prevent data leakage. If splitting occurred first, the preprocessing parameters (e.g., imputation values) calculated on training data might not match test data treatment, leading to inconsistent model evaluation.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services", "azure-ml-techniques"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-096", "question": "A company runs AutoML experiments with different validation configurations. With 10,000 rows of time-series sales data spanning 5 years, which validation approach is most appropriate?", "options": ["Random k-fold cross-validation", "Time-series cross-validation respecting temporal order", "Hold-out validation with random 80/20 split ignoring dates", "Monte Carlo validation with random sampling"], "correctAnswer": 1, "explanation": "For time-series data, validation must respect temporal order to simulate real-world forecasting scenarios. Time-series cross-validation uses a rolling window approach where training data always precedes validation data. Random validation would cause data leakage by using future information to predict the past.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques", "azure-ml-core-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-097", "question": "A deployed model's inference latency has increased from 50ms to 500ms over time. Investigation shows the endpoint receives more requests but hardware utilization remains low. What is the most likely cause?", "options": ["The model needs to be retrained with newer data", "Request queuing due to insufficient concurrency or instance count", "Data drift affecting prediction accuracy", "The model file size has increased"], "correctAnswer": 1, "explanation": "Low hardware utilization with increased latency typically indicates a concurrency bottleneck. Requests are queuing up waiting to be processed because the endpoint configuration (concurrent requests per node or number of instances) is insufficient for the increased load, even though the underlying hardware is not fully utilized.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-098", "question": "A data science team needs to compare Random Forest, XGBoost, and Neural Network models for a tabular classification problem while ensuring reproducibility. What Azure ML approach best supports this?", "options": ["Run each model manually in separate notebooks without logging", "Use Automated ML with experiment logging and model registry for comparison", "Train all models on the full dataset without validation", "Use the same random seed but different training datasets"], "correctAnswer": 1, "explanation": "Automated ML systematically explores multiple algorithms, automatically logs all experiments with parameters and metrics, and registers models for comparison. This ensures reproducibility through versioned code, tracked experiments, and registered models. Manual approaches lack proper tracking and comparability.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services", "azure-ml-techniques"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-099", "question": "An e-commerce company wants to predict customer lifetime value (CLV) and identify which factors most influence high-value customers. Which combination of techniques is most appropriate?", "options": ["Binary classification with feature importance analysis", "Regression for CLV prediction combined with feature importance or SHAP values", "Clustering only without prediction", "Anomaly detection to find high-value outliers"], "correctAnswer": 1, "explanation": "Customer Lifetime Value is a continuous variable best predicted with regression. Feature importance metrics (from tree-based models) or SHAP (SHapley Additive exPlanations) values help identify which factors most influence high CLV predictions, providing actionable business insights alongside predictions.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques", "azure-ml-core-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-100", "question": "A financial institution must explain why a loan application was rejected by their ML model to comply with regulations. Which Azure ML capability best addresses this requirement?", "options": ["Model registration only", "Model interpretability features and responsible AI dashboard for explainability", "Real-time endpoint logging", "Batch inference pipelines"], "correctAnswer": 1, "explanation": "Model interpretability features and the Responsible AI dashboard in Azure ML provide explanations for model predictions, including feature importance and SHAP values. These capabilities help meet regulatory requirements for explainable AI by showing which factors influenced specific loan decisions and ensuring fair, transparent outcomes.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services", "azure-ml-techniques"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-101", "question": "Which Azure service is best for detecting objects in images?", "options": ["Azure Bot Service", "Azure AI Vision", "Azure Synapse Analytics", "Azure DevOps"], "correctAnswer": 1, "explanation": "Azure AI Vision (formerly Computer Vision) provides capabilities for image analysis including object detection, image classification, and tagging. It can identify objects, people, scenes, and activities in images.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-102", "question": "What does OCR stand for in the context of computer vision?", "options": ["Optical Character Recognition", "Object Classification and Retrieval", "Optical Color Rendering", "Object Capture and Recognition"], "correctAnswer": 0, "explanation": "OCR stands for Optical Character Recognition, which is the technology used to convert images of typed, handwritten, or printed text into machine-encoded text. Azure AI Vision provides OCR capabilities through the Read API.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-103", "question": "Which Azure service would you use to build a custom image classification model for identifying specific types of manufacturing defects?", "options": ["Azure AI Vision", "Azure Custom Vision", "Azure Face Service", "Azure AI Document Intelligence"], "correctAnswer": 1, "explanation": "Azure Custom Vision allows you to build, deploy, and improve your own custom image classification and object detection models. You train the model with your own labeled images to recognize specific content relevant to your business domain.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-104", "question": "What is the primary purpose of facial detection in computer vision?", "options": ["To verify a person's identity against a database", "To locate and identify human faces in images or video", "To analyze emotional expressions on faces", "To compare two faces and determine if they match"], "correctAnswer": 1, "explanation": "Facial detection is the process of locating and identifying human faces within digital images or video streams. It simply finds where faces are located in an image, without identifying who the person is. Identity verification and comparison are functions of facial recognition.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-105", "question": "Which Azure service is specifically designed for analyzing video content?", "options": ["Azure AI Video Indexer", "Azure Media Player", "Azure Stream Analytics", "Azure Blob Storage"], "correctAnswer": 0, "explanation": "Azure AI Video Indexer (formerly Azure Video Analyzer for Media) uses AI to extract insights from videos, including transcription, face detection, object detection, and content moderation. It automatically analyzes video and audio content to make them searchable. Media Player, Stream Analytics, and Blob Storage do not provide AI-based video insight extraction.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-106", "question": "In image classification, what is a \"confidence score\"?", "options": ["The number of images used to train the model", "A value indicating how certain the model is about its prediction", "The processing time required to classify an image", "The resolution quality of the input image"], "correctAnswer": 1, "explanation": "A confidence score (or probability score) indicates the model's certainty about its prediction. It is typically expressed as a percentage or decimal between 0 and 1. Higher scores indicate greater confidence that the prediction is correct.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-107", "question": "What is the main difference between image classification and object detection?", "options": ["Image classification works on videos while object detection works on images", "Image classification labels the entire image while object detection locates specific objects within the image", "Object detection is faster than image classification", "Image classification requires more training data than object detection"], "correctAnswer": 1, "explanation": "Image classification assigns a single label to an entire image (e.g., \"this is a picture of a cat\"). Object detection goes further by identifying multiple objects in an image and providing their bounding box coordinates (e.g., \"cat at coordinates x,y with width w and height h\").", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-108", "question": "Which API feature of Azure AI Vision can extract printed and handwritten text from images?", "options": ["Image Analysis API", "Read API", "Face API", "Custom Vision API"], "correctAnswer": 1, "explanation": "The Read API is Azure AI Vision's OCR (Optical Character Recognition) feature that extracts printed and handwritten text from images and documents. It supports multiple languages and can handle dense text, multi-page documents, and various text styles.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-109", "question": "An older study guide recommends Azure AI Vision spatial analysis for tracking how shoppers move through store aisles. What is the status of that feature in 2026?", "options": ["Generally available in every Azure region", "Retired by Microsoft on March 30, 2025", "Available only through Azure Face identification", "Replaced by Azure AI Translator"], "correctAnswer": 1, "explanation": "Microsoft retired Azure AI Vision Spatial Analysis, the feature that analyzed people's presence and movement in camera video, on March 30, 2025, so a 2026 solution cannot use it. Face identification identifies people rather than tracking anonymous movement, and Translator works on text.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "medium", "lastUpdated": "2026-10-28", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-110", "question": "In Azure Custom Vision, what are the two main types of projects you can create?", "options": ["Classification and Regression", "Classification and Object Detection", "Detection and Segmentation", "Recognition and Analysis"], "correctAnswer": 1, "explanation": "Azure Custom Vision supports two main project types: Image Classification (assigns a label to an entire image) and Object Detection (identifies objects and their locations within an image using bounding boxes). These cover the majority of custom computer vision use cases.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-111", "question": "What is the purpose of face verification in Azure Face Service?", "options": ["To detect all faces in an image", "To determine if two faces belong to the same person", "To identify a person from a large database of faces", "To analyze facial expressions and emotions"], "correctAnswer": 1, "explanation": "Face verification (also called face comparison) checks whether two faces belong to the same person. It takes two face images as input and returns a similarity score indicating the likelihood they represent the same individual. This is a 1:1 comparison.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-112", "question": "A company needs to extract structured data from scanned invoices including vendor name, date, line items, and total amount. Which solution should they implement?", "options": ["Azure AI Vision Read API", "Azure AI Document Intelligence (formerly Form Recognizer)", "Azure Custom Vision", "Azure Face Service"], "correctAnswer": 1, "explanation": "Azure AI Document Intelligence (formerly Form Recognizer) is specifically designed to extract structured data from documents like invoices, receipts, and forms. It understands document layouts and can identify key-value pairs, tables, and specific fields without requiring extensive custom training.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-113", "question": "What is the difference between facial detection and facial recognition?", "options": ["Detection finds faces; recognition identifies who the person is", "Detection requires more computing power than recognition", "Recognition only works on photos while detection works on video", "There is no difference; they are the same technology"], "correctAnswer": 0, "explanation": "Facial detection locates faces in an image (finding \"where\" faces are), while facial recognition identifies who the person is by comparing against a database of known faces (finding \"who\" the person is). Detection is a prerequisite for recognition.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-114", "question": "When training a custom image classification model, what is the minimum recommended number of images per tag for Azure Custom Vision?", "options": ["5 images per tag", "15 images per tag", "50 images per tag", "100 images per tag"], "correctAnswer": 2, "explanation": "Azure Custom Vision recommends at least 50 images per tag for reliable training, though the service can work with as few as 15 images per tag. More images generally produce better model accuracy, especially when the images vary in background, lighting, and object positioning.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-115", "question": "Which iteration of a Custom Vision model should be used in production?", "options": ["The first iteration that achieved 50% accuracy", "The iteration with the highest precision and recall metrics", "Always the most recent iteration regardless of metrics", "The default iteration selected automatically by the service"], "correctAnswer": 1, "explanation": "You should select the iteration with the best performance metrics (precision, recall, and AP - Average Precision) for production use. Azure Custom Vision allows you to mark a specific iteration as the default for prediction endpoints, regardless of whether it is the most recent.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-116", "question": "What capability does Azure Video Indexer provide for video content?", "options": ["Video compression and format conversion", "Automatic transcription, face detection, and content moderation", "Real-time video streaming and broadcasting", "Video editing and special effects"], "correctAnswer": 1, "explanation": "Azure Video Indexer uses AI to extract deep insights from video and audio content, including automatic transcription, face detection and identification, emotion detection, keyframe extraction, scene segmentation, and content moderation for inappropriate material.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-117", "question": "A security system needs to detect when people enter a restricted area and send alerts. Which computer vision capability is most appropriate?", "options": ["Image classification", "Object detection with region of interest", "Facial recognition only", "OCR text extraction"], "correctAnswer": 1, "explanation": "Object detection with a defined region of interest (ROI) is ideal for this scenario. It can detect people (objects) entering specific zones in video frames. Azure AI Vision's Spatial Analysis feature once packaged this kind of zone alert for live video, but Microsoft retired it on March 30, 2025.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "medium", "lastUpdated": "2026-10-28", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-118", "question": "What does \"bounding box\" mean in object detection?", "options": ["The storage container for training images", "The rectangular coordinates defining where an object is located in an image", "The file format used to save detected objects", "The confidence threshold for accepting detection results"], "correctAnswer": 1, "explanation": "A bounding box is a rectangle defined by coordinates (typically x, y, width, height) that surrounds and identifies the location of a detected object in an image. Object detection models return bounding boxes along with class labels and confidence scores for each detected object.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-119", "question": "Which metric measures the proportion of actual positive cases that were correctly identified by a computer vision model?", "options": ["Precision", "Recall", "F1 Score", "Accuracy"], "correctAnswer": 1, "explanation": "Recall (also called sensitivity or true positive rate) measures the proportion of actual positives that were correctly identified. It answers: \"Of all the actual positive cases, how many did the model correctly find?\" High recall means few false negatives.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-120", "question": "What is the Azure AI Vision Image Analysis API capable of detecting?", "options": ["Only text in images", "Objects, people, scenes, activities, and visual content", "Only human faces", "Video content only"], "correctAnswer": 1, "explanation": "The Azure AI Vision Image Analysis API provides comprehensive image understanding including object detection, people detection, scene recognition, activity detection, image tagging, description generation, and adult/racy content detection. It offers a unified endpoint for multiple visual analysis tasks.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-121", "question": "A manufacturing company needs to detect microscopic defects on circuit boards with 99% accuracy. The defects vary in appearance and are rare events. What approach should they take?", "options": ["Use Azure AI Vision's built-in object detection without training", "Use Azure Custom Vision with anomaly detection and carefully balanced training data", "Use Azure Face Service to identify the operators", "Use the Read API to extract text from the circuit boards"], "correctAnswer": 1, "explanation": "For specialized defect detection with high accuracy requirements, Azure Custom Vision is appropriate. However, rare events (anomalies) require careful training data preparation, potentially using anomaly detection techniques or balancing techniques like oversampling the minority class. The built-in Azure AI Vision services are not trained for specific manufacturing defects.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-122", "question": "A team needs scene-level insights such as transcripts, detected faces, and on-screen text from hours of recorded store video. Which Azure service is designed for this?", "options": ["The OCR Read API applied to single frames only", "Azure AI Video Indexer", "Azure AI Translator", "Azure AI Language sentiment analysis"], "correctAnswer": 1, "explanation": "Azure AI Video Indexer extracts audio and visual insights such as transcripts, faces, scenes, and on-screen text (OCR) from recorded video. OCR on single frames misses the audio and timeline, Translator works on text, and sentiment analysis scores text opinions. Azure AI Vision's Spatial Analysis edge container, once used for live people counting, was retired on March 30, 2025.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "hard", "lastUpdated": "2026-10-28", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-123", "question": "A company trained a Custom Vision model that shows 95% precision but only 60% recall for detecting product defects. What does this indicate and how should they improve it?", "options": ["The model is finding too many false positives; increase training data variety", "The model is missing many actual defects; they need to add more positive examples and reduce the detection threshold", "The model is perfect; no changes are needed", "They should switch to facial recognition instead"], "correctAnswer": 1, "explanation": "High precision (95%) with low recall (60%) indicates the model is conservative - when it predicts a defect, it is usually correct, but it is missing many actual defects (false negatives). To improve recall, add more diverse training examples of defects, ensure balanced class representation, and potentially lower the probability threshold for detection.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-124", "question": "When using Azure Face Service, what is \"LargePersonGroup\" used for?", "options": ["To detect crowds in images", "To support identity verification against databases of up to 1 million people", "To recognize emotions in groups", "To process video streams with multiple people"], "correctAnswer": 1, "explanation": "LargePersonGroup is a container in Azure Face Service designed to hold up to 1 million persons for facial identification scenarios. Each person can have multiple faces registered. This is used for large-scale identity recognition systems like enterprise access control or large organization personnel identification.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-125", "question": "A retail analytics solution needs to track customer journey paths through a store while complying with GDPR privacy requirements. Which approach meets these requirements?", "options": ["Use facial recognition to identify repeat customers", "Collect only anonymous, aggregated movement counts and avoid storing biometric data or identities", "Store video footage indefinitely for analysis", "Use OCR to read customer loyalty cards at entrance"], "correctAnswer": 1, "explanation": "Privacy by design means collecting only what the analysis needs: anonymous, aggregated movement counts without identifying people or keeping biometric data. Facial recognition and loyalty-card reading identify individuals, and indefinite video storage keeps personal data far longer than needed. Azure AI Vision's Spatial Analysis feature, which once provided this kind of anonymous people tracking, was retired on March 30, 2025.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-solutions"], "difficulty": "hard", "lastUpdated": "2026-10-28", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-126", "question": "Which Azure service would you use to determine if customer feedback is positive, negative, or neutral?", "options": ["Azure Speech Service", "Azure AI Language service with sentiment analysis", "Azure Translator", "Azure Bot Service"], "correctAnswer": 1, "explanation": "Azure AI Language service provides sentiment analysis capabilities that evaluate text and return sentiment scores ranging from negative to positive. It can analyze text at both document and sentence levels, helping organizations understand customer opinions from feedback, reviews, and social media.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-127", "question": "What is the primary function of the Azure Speech Service?", "options": ["To translate documents between languages", "To convert speech to text and text to speech", "To analyze sentiment in written text", "To extract key phrases from documents"], "correctAnswer": 1, "explanation": "Azure Speech Service provides speech-to-text (STT) and text-to-speech (TTS) capabilities, enabling applications to transcribe spoken audio into text and convert text into natural-sounding speech. It also supports speech translation.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "easy", "lastUpdated": "2026-10-28", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-128", "question": "Which feature of Azure AI Language service identifies important terms and concepts in text?", "options": ["Sentiment Analysis", "Key Phrase Extraction", "Language Detection", "Named Entity Recognition"], "correctAnswer": 1, "explanation": "Key Phrase Extraction identifies the main talking points and concepts in unstructured text. It returns a list of strings denoting the key talking points in the input text, helping to quickly identify the most important themes without reading the entire document.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-129", "question": "What does Named Entity Recognition (NER) do in Azure AI Language?", "options": ["Recognizes proper names of people, organizations, locations, and other entities", "Recognizes the emotions of people mentioned in text", "Recognizes spelling and grammar errors", "Recognizes duplicate sentences in text"], "correctAnswer": 0, "explanation": "Named Entity Recognition (NER) identifies and categorizes entities in text into predefined categories such as person names, organizations, locations, dates, quantities, and more. It helps extract structured information from unstructured text documents.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-130", "question": "Which Azure service automatically identifies the language of a text document?", "options": ["Azure Translator", "Azure AI Language service", "Azure Speech Service", "Azure AI Document Intelligence"], "correctAnswer": 1, "explanation": "Azure AI Language service provides language detection capabilities that can identify the language of a text document and returns a language code (like \"en\" for English, \"es\" for Spanish) along with a confidence score. It supports over 100 languages.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-131", "question": "What is the main purpose of Azure Translator?", "options": ["To convert speech to text", "To translate text between different languages", "To analyze sentiment in multiple languages", "To recognize entities in foreign languages"], "correctAnswer": 1, "explanation": "Azure Translator is a cloud-based machine translation service that translates text between more than 100 languages and dialects. It supports text translation, document translation, and custom translation models for domain-specific terminology.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-132", "question": "What does Conversational Language Understanding (CLU) enable applications to do?", "options": ["Translate conversations in real-time", "Understand user intents and extract information from natural language utterances", "Record and store voice conversations", "Analyze the sentiment of voice tone"], "correctAnswer": 1, "explanation": "Conversational Language Understanding (CLU), part of Azure AI Language, enables applications to understand natural language input by identifying user intents (what the user wants to do) and extracting entities (relevant information) from conversational text. It powers chatbots and voice assistants.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-133", "question": "A company wants to build a chatbot that can answer questions about their product documentation. Which Azure service should they use?", "options": ["Azure Speech Service", "Azure AI Language service with question answering (custom question answering)", "Azure Translator", "Azure Video Indexer"], "correctAnswer": 1, "explanation": "Azure AI Language service's custom question answering feature (formerly QnA Maker) allows you to build a knowledge base from your existing documents and FAQs. The chatbot can then find the most appropriate answer for user questions from this knowledge base without requiring complex dialog management.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-134", "question": "In speech-to-text processing, what is the purpose of \"profanity filtering\"?", "options": ["To block inappropriate audio from being processed", "To mask or remove offensive words from the transcription output", "To filter out background noise from audio", "To prevent unauthorized users from accessing the service"], "correctAnswer": 1, "explanation": "Profanity filtering in Azure Speech Service masks or removes offensive words from the transcription output. Options typically include: none (no filtering), masked (replacing profanity with asterisks), removed (deleting profanity entirely), or tags (marking profanity with XML tags).", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-135", "question": "What is the difference between speech-to-text and speech translation?", "options": ["Speech-to-text transcribes audio in one language; speech translation transcribes and translates to another language", "Speech-to-text is faster than speech translation", "Speech translation only works with written text", "There is no difference between the two services"], "correctAnswer": 0, "explanation": "Speech-to-text transcribes spoken audio into written text in the same language. Speech translation goes further by transcribing the audio and then translating it into a different language, outputting the result as either text or synthesized speech.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-136", "question": "In Conversational Language Understanding (CLU), what is an \"intent\"?", "options": ["A programming error in the language model", "The action or goal the user wants to accomplish", "The programming language used to build the bot", "The database connection string"], "correctAnswer": 1, "explanation": "In CLU, an intent represents the action or goal the user wants to accomplish. For example, in a travel bot, \"BookFlight\" and \"CheckWeather\" would be intents. The model learns to map user utterances (like \"I need a flight to Paris\") to the correct intent.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-137", "question": "What are \"entities\" in the context of Conversational Language Understanding?", "options": ["Companies that use Azure services", "Pieces of information extracted from user utterances that are relevant to the intent", "Errors in the natural language processing", "Security permissions for the service"], "correctAnswer": 1, "explanation": "Entities are specific pieces of information extracted from user utterances that are relevant to fulfilling their intent. For example, in \"Book a flight to Paris on Friday,\" the entities would be destination (Paris) and date (Friday). CLU can extract prebuilt entities (dates, numbers) and custom entities.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-138", "question": "A customer service application needs to categorize support tickets by urgency based on the customer's message. Which NLP capability is most appropriate?", "options": ["Language detection only", "Sentiment analysis and key phrase extraction", "Text-to-speech conversion", "Document translation"], "correctAnswer": 1, "explanation": "Sentiment analysis can identify frustrated or angry customers (high urgency), while key phrase extraction can identify critical issues mentioned in the ticket. Combining these capabilities allows automatic categorization and prioritization of support tickets based on content analysis.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-139", "question": "What is the purpose of \"speaker diarization\" in Azure Speech Service?", "options": ["To separate speech from background music", "To separate and label different speakers in an audio recording", "To convert stereo audio to mono", "To detect the language being spoken"], "correctAnswer": 1, "explanation": "Speaker diarization separates and labels different speakers in an audio stream. For example, it can output \"Speaker 1: Hello\" and \"Speaker 2: Hi there,\" making it clear who spoke which words in conversations or meetings. It labels speakers generically and does not identify who they are; Speaker Recognition, which identified people by voice, was retired on September 30, 2025.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "medium", "lastUpdated": "2026-10-28", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-140", "question": "Which feature of Azure AI Language can identify personally identifiable information (PII) in documents?", "options": ["Sentiment Analysis", "Named Entity Recognition", "PII Detection and Redaction", "Language Detection"], "correctAnswer": 2, "explanation": "Azure AI Language provides PII detection capabilities that can identify and optionally redact sensitive information such as phone numbers, email addresses, credit card numbers, and personal names from text. This helps organizations comply with privacy regulations like GDPR and HIPAA.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-141", "question": "What is \"neural text-to-speech\" in Azure Speech Service?", "options": ["A method to convert brain signals to speech", "Deep neural network-based speech synthesis that produces natural-sounding voices", "Speech recognition for neural network researchers", "A type of speech therapy"], "correctAnswer": 1, "explanation": "Neural text-to-speech uses deep neural networks to synthesize speech that sounds nearly indistinguishable from human voices. It produces more natural prosody, intonation, and rhythm compared to traditional concatenative or parametric speech synthesis methods.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-142", "question": "In sentiment analysis, what do \"opinion mining\" or \"aspect-based sentiment analysis\" refer to?", "options": ["Mining cryptocurrency based on sentiment", "Analyzing sentiment toward specific aspects or features mentioned in text", "Collecting user opinions through surveys", "Mining data from opinion websites only"], "correctAnswer": 1, "explanation": "Opinion mining (aspect-based sentiment analysis) goes beyond overall document sentiment to identify sentiment toward specific aspects or features mentioned in text. For example, in a restaurant review, it can identify positive sentiment toward food but negative sentiment toward service.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-143", "question": "What is the function of \"speech synthesis markup language (SSML)\" in text-to-speech?", "options": ["To translate speech to different languages", "To control pronunciation, prosody, and other speech characteristics using XML markup", "To recognize speech patterns", "To compress audio files"], "correctAnswer": 1, "explanation": "SSML is an XML-based markup language that allows developers to control how text is converted to speech. It can specify pronunciation, stress, pitch, speaking rate, volume, and pauses, enabling fine-tuned control over the synthesized voice output for more natural-sounding speech.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-144", "question": "Which Azure service would you use to build an application that translates spoken conversations in real-time between English and Spanish speakers?", "options": ["Azure Translator Text API only", "Azure Speech Service with speech translation", "Azure AI Language service", "Azure Bot Service"], "correctAnswer": 1, "explanation": "Azure Speech Service's speech translation capability is designed for real-time speech-to-speech translation. It can transcribe spoken input, translate it to another language, and output the result as either text or synthesized speech, enabling natural multilingual conversations.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-145", "question": "What is a \"language model\" in the context of NLP?", "options": ["A person who speaks multiple languages", "A statistical or neural network model that understands and generates human language", "A database of vocabulary words", "A translation dictionary"], "correctAnswer": 1, "explanation": "A language model is a statistical or machine learning model trained on large amounts of text data to understand patterns in language. It can predict the likelihood of word sequences, generate text, understand context, and power various NLP tasks like translation, summarization, and question answering.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-146", "question": "A global call center needs to transcribe customer calls in 20 languages, detect sentiment, identify key phrases, and extract entities in real-time. Which architecture is most appropriate?", "options": ["Use Azure Speech Service for transcription, then send text to Azure AI Language for analysis", "Use Azure Translator to convert all calls to English first", "Store all calls and process them overnight in batches", "Use only Azure Video Indexer for all processing"], "correctAnswer": 0, "explanation": "The optimal architecture involves a pipeline: Azure Speech Service performs real-time speech-to-text transcription in the appropriate language, and the resulting text is sent to Azure AI Language service for sentiment analysis, key phrase extraction, and NER. This modular approach leverages each service's strengths and supports all required languages.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-147", "question": "In a CLU model, an utterance \"I need to book a flight from Seattle to Boston next Tuesday\" is mapped to the \"BookFlight\" intent. What are the entities that should be extracted?", "options": ["Only \"flight\"", "Origin (Seattle), Destination (Boston), and Date (next Tuesday)", "Only \"next Tuesday\"", "The entire sentence as one entity"], "correctAnswer": 1, "explanation": "The entities in this utterance are the specific pieces of information needed to fulfill the booking: Origin (Seattle), Destination (Boston), and Date (next Tuesday). These are the parameters that the application needs to execute the flight booking intent. The word \"flight\" is the domain but not an extractable entity in this context.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-148", "question": "A healthcare application needs to analyze patient notes to extract medical conditions, medications, and dosages while ensuring HIPAA compliance. Which approach should be used?", "options": ["Use standard Named Entity Recognition with public healthcare data", "Use Azure AI Language's custom NER with healthcare-specific training data, ensuring data is processed in a HIPAA-compliant environment with proper encryption", "Use Azure Translator to translate the notes to another language first", "Use sentiment analysis only"], "correctAnswer": 1, "explanation": "Healthcare applications require domain-specific entity recognition for medical terminology (conditions, medications, dosages). Azure AI Language's custom NER allows training on healthcare-specific data. HIPAA compliance requires proper data handling agreements, encryption in transit and at rest, and potentially deploying in a healthcare-compliant environment like Azure with Business Associate Agreements.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-149", "question": "When building a question answering system using Azure AI Language, what is the purpose of \"active learning\"?", "options": ["To reduce the cost of the service", "To continuously improve the model by suggesting alternative questions for review based on real user queries", "To translate questions to different languages", "To prevent users from asking off-topic questions"], "correctAnswer": 1, "explanation": "Active learning in Azure AI Language's question answering feature monitors real user queries that the model is uncertain about and suggests them for review. Subject matter experts can then add these variations to the knowledge base, continuously improving the model's accuracy without requiring manual review of all queries.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-150", "question": "A multilingual bot needs to understand that \"I want to reserve a table\" and \"Table booking please\" and \"Reservar una mesa\" all represent the same user intent. Which capabilities are required?", "options": ["Only Azure Translator", "Conversational Language Understanding with multilingual training and language detection", "Only text-to-speech", "Only key phrase extraction"], "correctAnswer": 1, "explanation": "This scenario requires Conversational Language Understanding (CLU) trained with multilingual utterances to recognize the same intent across languages. While Azure Translator could translate inputs to a single language, a multilingual CLU model natively understands the intent in all supported languages, providing better accuracy and lower latency without the translation step.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-151", "question": "What is generative AI?", "options": ["AI that can only classify images", "AI that creates new content such as text, images, or code based on training data", "AI that plays chess and board games", "AI that only performs data analysis"], "correctAnswer": 1, "explanation": "Generative AI refers to artificial intelligence systems that can create new content including text, images, audio, code, and video. These models learn patterns from training data and generate novel outputs, such as GPT models for text or DALL-E for images.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-152", "question": "Which Azure service provides access to OpenAI GPT models, gpt-image models, and embeddings?", "options": ["Azure Machine Learning", "Azure OpenAI Service", "Azure AI Language", "Azure Bot Service"], "correctAnswer": 1, "explanation": "Azure OpenAI Service provides REST API access to OpenAI models, including GPT models for text, gpt-image models for image generation (DALL-E 3 was retired on March 4, 2026), and embedding models. It combines OpenAI's models with Azure's security and compliance features.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "easy", "lastUpdated": "2026-10-28", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-153", "question": "What is the primary purpose of prompt engineering?", "options": ["To train machine learning models from scratch", "To design effective inputs that guide AI models to produce desired outputs", "To create hardware for AI acceleration", "To manage Azure resource deployments"], "correctAnswer": 1, "explanation": "Prompt engineering is the practice of designing and refining input prompts to guide large language models toward producing accurate, relevant, and useful outputs. Well-crafted prompts improve model performance without requiring model retraining.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-154", "question": "What is zero-shot prompting?", "options": ["Providing many examples before asking the model to perform a task", "Asking the model to perform a task without providing any examples", "Training the model with zero data samples", "Using the model without an Azure subscription"], "correctAnswer": 1, "explanation": "Zero-shot prompting involves asking a model to perform a task directly without providing any examples. This tests the model's pre-trained knowledge and generalization capabilities. Large language models like GPT-4 can often perform many tasks effectively with zero-shot prompting.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-155", "question": "What is few-shot prompting?", "options": ["Running the model for only a few seconds", "Providing a few examples to guide the model before the main task", "Using only small models", "Training with minimal compute resources"], "correctAnswer": 1, "explanation": "Few-shot prompting provides the model with a small number of examples (typically 1-10) demonstrating the desired input-output pattern before presenting the actual task. This technique improves model performance on specific tasks by showing the pattern to follow.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-156", "question": "What is chain-of-thought prompting?", "options": ["Connecting multiple AI models in sequence", "Prompting the model to show its reasoning steps before giving the final answer", "Creating a network of training data", "Linking Azure services together"], "correctAnswer": 1, "explanation": "Chain-of-thought prompting encourages the model to break down complex problems into intermediate reasoning steps. By showing its work, the model often arrives at more accurate answers for tasks requiring logic, math, or multi-step reasoning.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-157", "question": "Which GPT model feature allows processing both text and images in the same input?", "options": ["Text completion only", "Multimodal capabilities", "Token streaming", "Batch processing"], "correctAnswer": 1, "explanation": "Multimodal capabilities in GPT-4 and later models allow the model to understand and reason across multiple input types including text and images. Users can ask questions about images, have the model analyze visual content, and receive text-based responses.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-158", "question": "What is the purpose of content filtering in Azure OpenAI Service?", "options": ["To reduce API costs", "To detect and prevent harmful content generation", "To speed up response times", "To limit token usage"], "correctAnswer": 1, "explanation": "Azure OpenAI Service includes content filtering to detect and mitigate potentially harmful content including hate speech, self-harm, sexual content, and violence. This helps organizations deploy AI responsibly and maintain safety standards.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts", "azure-responsible-ai"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-159", "question": "What are tokens in the context of large language models?", "options": ["Authentication keys for API access", "Units of text (words or parts of words) that the model processes", "Digital currency for Azure services", "Security certificates"], "correctAnswer": 1, "explanation": "Tokens are the basic units of text that language models process. A token can be a whole word, part of a word, or punctuation. Models have token limits for input and output, and pricing is often based on token usage.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-160", "question": "What is the context window of a language model?", "options": ["The browser window used to access the model", "The maximum amount of text (in tokens) the model can process in a single request", "The geographical region where the model is hosted", "The user interface for the model"], "correctAnswer": 1, "explanation": "The context window is the maximum number of tokens a language model can process in a single request, including both input prompt and generated output. Larger context windows allow for longer conversations and document analysis.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-161", "question": "Which Microsoft 365 feature provides AI-powered assistance across Office applications?", "options": ["Azure Machine Learning", "Microsoft 365 Copilot", "Power Automate", "SharePoint AI"], "correctAnswer": 1, "explanation": "Microsoft 365 Copilot integrates AI capabilities across Office applications like Word, Excel, PowerPoint, Outlook, and Teams. It helps users draft documents, analyze data, create presentations, and manage communications using generative AI.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-copilot-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-162", "question": "What is GitHub Copilot?", "options": ["A code repository hosting service", "An AI pair programmer that suggests code completions", "A version control system", "A project management tool"], "correctAnswer": 1, "explanation": "GitHub Copilot is an AI-powered code completion tool that suggests code as developers type. It's powered by OpenAI Codex and can generate function implementations, documentation, and even entire code blocks based on comments and context.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-copilot-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-163", "question": "What is Copilot Studio used for?", "options": ["Creating custom AI copilots for specific business scenarios", "Writing code for mobile applications", "Designing database schemas", "Managing Azure subscriptions"], "correctAnswer": 0, "explanation": "Copilot Studio is a low-code platform for creating custom AI copilots. Organizations can build tailored conversational AI experiences that integrate with their data and workflows, extending Microsoft Copilot capabilities for specific business needs.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-copilot-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-164", "question": "What are gpt-image models in Azure OpenAI Service?", "options": ["A text classification model", "An AI model that generates images from text descriptions", "A speech recognition service", "A data analytics tool"], "correctAnswer": 1, "explanation": "gpt-image models are generative AI models that create and edit images from text prompts. They replaced DALL-E 3, which Microsoft retired in Azure OpenAI on March 4, 2026.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "easy", "lastUpdated": "2026-10-28", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-165", "question": "What is the purpose of embeddings in Azure OpenAI Service?", "options": ["To encrypt API communications", "To convert text into numerical vectors for similarity search", "To compress image files", "To authenticate users"], "correctAnswer": 1, "explanation": "Embeddings convert text into numerical vectors that capture semantic meaning. These vectors enable similarity searches, clustering, and classification tasks. Applications include semantic search, recommendation systems, and anomaly detection.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-166", "question": "What is fine-tuning in the context of large language models?", "options": ["Adjusting the user interface", "Training a pre-trained model on specific data to improve performance on specialized tasks", "Optimizing network connections", "Reducing model file size"], "correctAnswer": 1, "explanation": "Fine-tuning involves taking a pre-trained language model and training it further on domain-specific data. This adapts the model for specialized tasks or industries while requiring less data and compute than training from scratch.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-167", "question": "What is a key limitation of large language models?", "options": ["They can only process English text", "They may generate plausible-sounding but incorrect information (hallucinations)", "They require internet connectivity at all times", "They can only run on supercomputers"], "correctAnswer": 1, "explanation": "Large language models can produce hallucinations—confidently stated but incorrect or fabricated information. This is because they predict likely text patterns rather than accessing verified facts. Users should verify important information from LLM outputs.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-168", "question": "What is abuse monitoring in Azure OpenAI Service?", "options": ["Tracking API usage costs", "Detecting and preventing misuse of AI services", "Monitoring server performance", "Managing user subscriptions"], "correctAnswer": 1, "explanation": "Abuse monitoring in Azure OpenAI Service detects potential misuse such as attempts to generate harmful content, jailbreak attempts, or other policy violations. This helps maintain platform integrity and responsible AI usage.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts", "azure-responsible-ai"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-169", "question": "What is retrieval-augmented generation (RAG)?", "options": ["A method to increase model training speed", "Combining information retrieval with text generation to ground responses in specific data", "A technique for compressing models", "A way to reduce API latency"], "correctAnswer": 1, "explanation": "Retrieval-augmented generation combines information retrieval from a knowledge base with language model generation. The model retrieves relevant documents first, then generates answers based on that retrieved information, improving accuracy and reducing hallucinations.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-170", "question": "Which approach helps reduce hallucinations when using LLMs for question answering?", "options": ["Using longer prompts", "Grounding the model with retrieved context from verified sources", "Increasing the temperature setting", "Removing content filters"], "correctAnswer": 1, "explanation": "Grounding LLMs with retrieved context from verified sources helps reduce hallucinations. By providing relevant, factual information in the prompt, the model bases its answers on provided context rather than relying solely on its training data, improving accuracy.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-171", "question": "What does temperature control in language model generation?", "options": ["The physical temperature of servers", "The randomness or creativity of the model's output", "The processing speed", "The number of tokens used"], "correctAnswer": 1, "explanation": "Temperature controls the randomness in language model output. Lower temperatures (e.g., 0.2) produce more focused, deterministic responses, while higher temperatures (e.g., 0.9) generate more diverse, creative outputs. It's useful for balancing consistency and creativity.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-172", "question": "What is the purpose of system messages in Azure OpenAI Service?", "options": ["To configure server hardware", "To set the behavior and context for the AI assistant", "To manage user authentication", "To track API usage"], "correctAnswer": 1, "explanation": "System messages in Azure OpenAI Service set the context, behavior, and constraints for the AI assistant. They define the persona, tone, and guidelines the model should follow throughout the conversation, such as \"You are a helpful technical assistant.\"", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-173", "question": "Which Microsoft tool allows developers to build AI-powered search experiences?", "options": ["Azure DevOps", "Azure AI Search with vector capabilities", "Visual Studio Code", "Microsoft Teams"], "correctAnswer": 1, "explanation": "Azure AI Search (formerly Azure Cognitive Search) with vector capabilities enables developers to build sophisticated search experiences. It supports vector search for semantic similarity, hybrid search combining keyword and vector approaches, and integration with Azure OpenAI embeddings.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-174", "question": "What is the main benefit of using Azure OpenAI Service instead of directly using OpenAI's API?", "options": ["Lower cost for all use cases", "Enterprise security, compliance, and Azure integration", "Access to more powerful models", "Unlimited token usage"], "correctAnswer": 1, "explanation": "Azure OpenAI Service provides OpenAI's models with the added benefits of Azure's enterprise security, compliance certifications, private networking, and integration with Azure services. This makes it suitable for enterprise deployments requiring data governance.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-175", "question": "What is prompt injection in the context of AI security?", "options": ["Adding more tokens to a prompt", "Malicious attempts to override system instructions through user input", "Injecting code into the AI model", "Speeding up prompt processing"], "correctAnswer": 1, "explanation": "Prompt injection is an attack where malicious users craft inputs designed to override or bypass system instructions in language models. For example, attempting to make the model ignore safety guidelines or reveal system prompts through cleverly constructed user messages.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts", "azure-responsible-ai"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-176", "question": "Which technique involves breaking a complex task into smaller subtasks handled by multiple AI prompts?", "options": ["Single-shot prompting", "Prompt chaining", "Temperature adjustment", "Token reduction"], "correctAnswer": 1, "explanation": "Prompt chaining breaks complex tasks into a sequence of simpler prompts where the output of one becomes input for the next. This modular approach improves reliability, makes debugging easier, and allows handling tasks too complex for a single prompt.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-177", "question": "What is the Azure OpenAI Service feature that allows models to call external functions or APIs?", "options": ["Model training", "Function calling", "Token streaming", "Batch processing"], "correctAnswer": 1, "explanation": "Function calling in Azure OpenAI Service allows models to intelligently determine when to call external functions or APIs based on user input. The model outputs a structured function call that the application can execute, then the results can be fed back to the model.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-178", "question": "What is the primary purpose of Azure AI Content Safety?", "options": ["To accelerate model training", "To detect harmful content across text and images", "To manage API keys", "To optimize model performance"], "correctAnswer": 1, "explanation": "Azure AI Content Safety detects harmful content across text and images including hate speech, self-harm, sexual content, and violence. It can be used independently or integrated with other Azure AI services to build safer applications.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts", "azure-responsible-ai"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-179", "question": "Which factor should be considered when selecting a GPT model for a specific use case?", "options": ["Only the model name", "Capabilities, context window, cost, and latency requirements", "The color of the Azure portal", "The number of developers on the team"], "correctAnswer": 1, "explanation": "Selecting a GPT model requires considering multiple factors: capabilities needed for the task, context window size for input length, cost per token for budget constraints, and latency requirements for response speed. Different models offer different trade-offs.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-180", "question": "What is the main advantage of using vector databases with generative AI?", "options": ["They store data in alphabetical order", "They enable efficient semantic search and retrieval based on meaning", "They reduce the need for any AI models", "They automatically generate training data"], "correctAnswer": 1, "explanation": "Vector databases store embeddings (numerical representations of meaning) and enable efficient similarity search based on semantic meaning rather than keyword matching. This allows finding conceptually related content, essential for RAG and semantic search applications.", "exams": ["azure-ai-900"], "category": "azure-generative-ai", "topics": ["azure-generative-ai-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-181", "question": "What type of machine learning uses labeled training data with known outcomes?", "options": ["Unsupervised learning", "Supervised learning", "Reinforcement learning", "Transfer learning"], "correctAnswer": 1, "explanation": "Supervised learning uses labeled training data where both input features and correct outputs are provided. The algorithm learns to map inputs to outputs based on these examples, enabling prediction on new, unseen data.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-182", "question": "Which Azure service is specifically designed for building conversational AI interfaces?", "options": ["Azure Synapse Analytics", "Azure Bot Service", "Azure DevOps", "Azure Active Directory"], "correctAnswer": 1, "explanation": "Azure Bot Service provides an integrated environment for building, testing, and deploying conversational AI bots. It integrates with Azure AI Language Service for natural language understanding and supports multiple channels including web, Teams, and Slack.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-183", "question": "What is the primary function of Azure AI Vision's Image Analysis feature?", "options": ["Storing images in the cloud", "Extracting information and insights from images", "Compressing image file sizes", "Converting images to video"], "correctAnswer": 1, "explanation": "Azure AI Vision's Image Analysis extracts rich information from images including objects, scenes, text (OCR), faces, and image descriptions. It uses pre-trained models to provide insights about visual content without requiring custom model training.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-184", "question": "Which principle of responsible AI emphasizes treating all people fairly?", "options": ["Privacy and security", "Fairness", "Transparency", "Accountability"], "correctAnswer": 1, "explanation": "Fairness is a core principle of responsible AI that emphasizes treating all individuals and groups equitably. AI systems should not discriminate based on protected characteristics like race, gender, age, or disability, and should be tested for biased outcomes.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-185", "question": "What type of neural network is commonly used for image recognition tasks?", "options": ["Recurrent Neural Networks (RNN)", "Convolutional Neural Networks (CNN)", "Feedforward Neural Networks", "Boltzmann Machines"], "correctAnswer": 1, "explanation": "Convolutional Neural Networks (CNNs) are specifically designed for image processing tasks. They use convolutional layers to automatically detect features like edges, textures, and patterns, making them highly effective for image classification and object detection.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-186", "question": "Which Azure service enables custom machine learning model development with a visual interface?", "options": ["Azure Virtual Machines", "Azure Machine Learning designer", "Azure Storage", "Azure Functions"], "correctAnswer": 1, "explanation": "Azure Machine Learning designer provides a drag-and-drop visual interface for building, testing, and deploying machine learning models. It allows users to create ML pipelines using pre-built modules without writing code, while also supporting custom code when needed.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-services"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-187", "question": "What is the purpose of Named Entity Recognition (NER) in NLP?", "options": ["To count words in a document", "To identify and classify named entities like people, organizations, and locations", "To translate text between languages", "To check spelling and grammar"], "correctAnswer": 1, "explanation": "Named Entity Recognition (NER) identifies and categorizes named entities in text such as person names, organizations, locations, dates, and quantities. It helps extract structured information from unstructured text for analysis and indexing.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-188", "question": "Which Azure AI Vision feature can detect and identify human faces in images?", "options": ["Object detection", "Face detection and analysis", "Optical character recognition", "Image captioning"], "correctAnswer": 1, "explanation": "Azure AI Face detects human faces in images and returns face location, landmarks, and attributes such as head pose, glasses, and mask; Microsoft retired the emotion and gender attributes. Face identification and verification are Limited Access features used for identity verification and access control.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "easy", "lastUpdated": "2026-10-28", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-189", "question": "What is clustering in unsupervised machine learning?", "options": ["Grouping data points into categories based on similarity without pre-defined labels", "Organizing training data alphabetically", "Combining multiple AI models", "Storing data in cloud clusters"], "correctAnswer": 0, "explanation": "Clustering is an unsupervised learning technique that groups similar data points together based on their features. Unlike classification, clustering doesn't require pre-labeled data and discovers natural groupings in the data automatically.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-techniques"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-190", "question": "Which responsible AI principle focuses on understanding how AI systems make decisions?", "options": ["Reliability and safety", "Transparency", "Inclusiveness", "Privacy"], "correctAnswer": 1, "explanation": "Transparency in responsible AI means understanding and explaining how AI systems make decisions. This includes documenting how models work, what data they use, and being able to explain why specific decisions were made, which builds trust and enables debugging.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-191", "question": "What does Azure AI Language Service's sentiment analysis determine?", "options": ["The language of the text", "The emotional tone (positive, negative, neutral) of text", "The grammar correctness", "The reading level"], "correctAnswer": 1, "explanation": "Sentiment analysis in Azure AI Language Service evaluates text to determine the emotional tone, categorizing it as positive, negative, neutral, or mixed. It can also provide confidence scores and aspect-based sentiment for specific topics within the text.", "exams": ["azure-ai-900"], "category": "azure-nlp", "topics": ["azure-nlp-solutions"], "difficulty": "easy", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-192", "question": "What is the purpose of Azure Custom Vision?", "options": ["To create pre-built computer vision models", "To build and deploy custom image classification and object detection models", "To store large image collections", "To convert images to text documents"], "correctAnswer": 1, "explanation": "Azure Custom Vision enables users to build custom image classification and object detection models using their own labeled images. It provides a simple interface for training models specific to domain needs without requiring deep learning expertise.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-193", "question": "Which metric is commonly used to evaluate classification model performance?", "options": ["Lines of code written", "Accuracy, precision, recall, and F1 score", "Server response time", "Number of features used"], "correctAnswer": 1, "explanation": "Classification models are evaluated using metrics like accuracy (overall correctness), precision (true positives among predicted positives), recall (true positives among actual positives), and F1 score (harmonic mean of precision and recall). These help assess model quality.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-194", "question": "What is overfitting in machine learning?", "options": ["When a model performs well on training data but poorly on new data", "When a model trains too quickly", "When training data is too large", "When the model uses too few features"], "correctAnswer": 0, "explanation": "Overfitting occurs when a model learns the training data too well, including noise and patterns that don't generalize. An overfitted model performs well on training data but poorly on new, unseen data because it hasn't learned generalizable patterns.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-195", "question": "Which Azure service provides pre-built AI capabilities for speech recognition and synthesis?", "options": ["Azure AI Search", "Azure AI Speech", "Azure Data Lake", "Azure Cosmos DB"], "correctAnswer": 1, "explanation": "Azure AI Speech provides comprehensive speech capabilities including speech-to-text (recognition), text-to-speech (synthesis), and speech translation. These pre-built AI features can be integrated into applications without ML expertise.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "easy", "lastUpdated": "2026-10-28", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-196", "question": "What is the purpose of Azure AI Document Intelligence?", "options": ["To create Word documents", "To extract structured data from documents like forms and invoices", "To store document files", "To convert documents to images"], "correctAnswer": 1, "explanation": "Azure AI Document Intelligence (formerly Form Recognizer) extracts structured data from documents including forms, invoices, receipts, and identity documents. It uses machine learning to understand document layouts and extract key-value pairs and tables.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-ai-workloads-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-197", "question": "Which technique helps prevent overfitting in machine learning models?", "options": ["Using more complex models", "Cross-validation and regularization", "Training on only one dataset", "Removing all test data"], "correctAnswer": 1, "explanation": "Cross-validation evaluates model performance across different data splits to assess generalization. Regularization techniques like L1/L2 penalize complex models to prevent them from fitting noise. Both help create models that perform well on new data.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "hard", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-198", "question": "What is the key difference between classification and regression in machine learning?", "options": ["Classification predicts categories; regression predicts continuous values", "Classification is faster than regression", "Classification uses more data", "Regression is only for images"], "correctAnswer": 0, "explanation": "Classification predicts discrete categories or classes (e.g., spam/not spam, cat/dog), while regression predicts continuous numerical values (e.g., house prices, temperature). This fundamental difference determines the algorithms and evaluation metrics used.", "exams": ["azure-ai-900"], "category": "azure-ml-fundamentals", "topics": ["azure-ml-core-concepts"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-199", "question": "Which Azure AI service is designed for extracting insights from video content?", "options": ["Azure AI Video Indexer (formerly Azure Video Analyzer for Media)", "Azure Blob Storage", "Azure SQL Database", "Azure Monitor"], "correctAnswer": 0, "explanation": "Azure AI Video Indexer extracts insights from videos including speech transcription, face detection and identification, sentiment analysis, keyframe extraction, and topic detection. It enables searchable video libraries and automated content analysis.", "exams": ["azure-ai-900"], "category": "azure-computer-vision", "topics": ["azure-vision-services"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-900-q-200", "question": "Which principle of responsible AI ensures AI systems work reliably under normal and unexpected conditions?", "options": ["Inclusiveness", "Reliability and safety", "Transparency", "Accountability"], "correctAnswer": 1, "explanation": "Reliability and safety ensures AI systems perform consistently under expected conditions and handle unexpected situations gracefully. This includes rigorous testing, monitoring, and having fail-safes to prevent harm when systems encounter edge cases or errors.", "exams": ["azure-ai-900"], "category": "azure-ai-workloads", "topics": ["azure-responsible-ai"], "difficulty": "medium", "lastUpdated": "2026-03-01", "source": "azure-ai-900"}, {"id": "azure-ai-901-001", "question": "Which two skill domains make up the Microsoft AI-901 exam blueprint?", "options": ["Identify AI concepts and responsibilities, and Implement AI solutions by using Microsoft Foundry", "Machine learning operations, and Data engineering on Azure", "Designing Azure infrastructure, and Securing Azure networks", "Power Platform automation, and Microsoft 365 administration"], "correctAnswer": 0, "explanation": "The refreshed AI-901 exam is organized into two skill areas: Identify AI concepts and responsibilities (40-45%) and Implement AI solutions by using Microsoft Foundry (55-60%). The first is conceptual and the second is hands-on with the Foundry platform.", "exams": ["azure-ai-901"], "category": "ai-concepts", "topics": ["exam-blueprint"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Machine learning operations and data engineering are covered in role-based exams such as DP-100, not in the fundamentals-level AI-901.", "2": "Infrastructure and network security are Azure administrator topics (AZ-104, AZ-500), not the AI fundamentals blueprint.", "3": "Power Platform and Microsoft 365 administration are separate certification tracks unrelated to AI-901."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-002", "question": "What is the unified Microsoft platform for building and deploying AI applications and agents that AI-901 is built around?", "options": ["Microsoft Foundry", "Microsoft Power BI", "Microsoft Sentinel", "Microsoft Defender"], "correctAnswer": 0, "explanation": "Microsoft Foundry (previously Azure AI Foundry and Azure AI Studio) is Microsoft's unified platform for building, deploying, and managing AI applications and agents on Azure. The AI-901 exam was redesigned around Foundry as the primary developer experience.", "exams": ["azure-ai-901"], "category": "ai-concepts", "topics": ["microsoft-foundry"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Power BI is a business analytics and data visualization tool, not an AI application development platform.", "2": "Microsoft Sentinel is a cloud-native SIEM and security analytics service, not an AI app-building platform.", "3": "Microsoft Defender is a security product family, not the AI development platform AI-901 covers."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-006", "question": "An AI system must protect personal data and give users control over how their information is used. Which responsible AI principle applies?", "options": ["Privacy and security", "Transparency", "Reliability and safety", "Accountability"], "correctAnswer": 0, "explanation": "Privacy and security means AI systems must protect data and respect user privacy, securing information against misuse throughout its lifecycle. This includes safeguarding training data and user inputs.", "exams": ["azure-ai-901"], "category": "responsible-ai", "topics": ["privacy-security"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Transparency is about explainability, not protecting personal data.", "2": "Reliability and safety concern consistent operation, not data protection.", "3": "Accountability is about human responsibility, not directly about safeguarding personal data."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-007", "question": "Designing an AI solution so that it is accessible to people with disabilities best reflects which responsible AI principle?", "options": ["Inclusiveness", "Fairness", "Transparency", "Privacy and security"], "correctAnswer": 0, "explanation": "Inclusiveness means AI systems should empower everyone and engage people across abilities and backgrounds, including accessibility for people with disabilities. It ensures the benefits of AI reach diverse populations.", "exams": ["azure-ai-901"], "category": "responsible-ai", "topics": ["inclusiveness"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Fairness is about non-discrimination in outcomes, not specifically accessibility.", "2": "Transparency concerns explainability, not accessibility for people with disabilities.", "3": "Privacy and security concern data protection, not inclusive design."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-008", "question": "Users should understand how an AI system reaches its decisions and what its limitations are. Which principle does this describe?", "options": ["Transparency", "Accountability", "Inclusiveness", "Reliability and safety"], "correctAnswer": 0, "explanation": "Transparency means people should be able to understand how AI systems make decisions and be aware of their capabilities and limitations. Clear documentation and explainability tools support this principle.", "exams": ["azure-ai-901"], "category": "responsible-ai", "topics": ["transparency"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Accountability is about people being responsible for AI outcomes, not about explaining how decisions are made.", "2": "Inclusiveness is about empowering diverse users, not explainability.", "3": "Reliability and safety concern consistent operation, not understandability of decisions."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-009", "question": "Which responsible AI principle states that people, not the AI system itself, must be answerable for how an AI system operates?", "options": ["Accountability", "Transparency", "Fairness", "Privacy and security"], "correctAnswer": 0, "explanation": "Accountability means the people who design and deploy AI systems are responsible for how those systems operate, including meeting legal and ethical standards. Governance frameworks help organizations uphold accountability.", "exams": ["azure-ai-901"], "category": "responsible-ai", "topics": ["accountability"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Transparency is about understandability of the system, not about who is answerable for it.", "2": "Fairness concerns equitable treatment, not responsibility for the system.", "3": "Privacy and security concern data protection, not human responsibility for outcomes."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-010", "question": "A content team wants to block a generative AI app from producing hateful or violent text. Which Azure capability is designed for this?", "options": ["Azure AI Content Safety", "Azure Monitor", "Azure Key Vault", "Azure Resource Manager"], "correctAnswer": 0, "explanation": "Azure AI Content Safety detects and filters harmful content such as hate, violence, self-harm, and sexual material in both text and images. It supports the responsible AI principles of reliability, safety, and harm mitigation in generative apps.", "exams": ["azure-ai-901"], "category": "responsible-ai", "topics": ["content-safety"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Azure Monitor collects telemetry and metrics; it does not filter harmful AI-generated content.", "2": "Azure Key Vault stores secrets and keys; it has no content moderation role.", "3": "Azure Resource Manager deploys and manages resources; it does not screen generated content."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-011", "question": "Which statement best describes how a generative AI language model produces its output?", "options": ["It predicts the next token in a sequence based on patterns learned from large amounts of text", "It looks up the exact answer from a fixed database of facts", "It runs a fixed if-then rule set written by engineers", "It searches the live web for each response in real time by default"], "correctAnswer": 0, "explanation": "Generative language models are trained on large text corpora and generate output by predicting the most probable next token given the preceding context. They produce fluent, original text rather than retrieving fixed answers.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["how-models-work"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Models do not look up exact answers from a fixed database; they generate text probabilistically.", "2": "Generative models are not hand-coded rule sets; they learn statistical patterns from data.", "3": "By default a base model does not search the live web; it relies on its trained parameters unless augmented with retrieval."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-013", "question": "Which type of model creates a numeric vector representation of text so that similar meanings are placed close together?", "options": ["An embedding model", "A speech synthesis model", "A reinforcement-only model", "A rule-based parser"], "correctAnswer": 0, "explanation": "Embedding models convert text into dense numeric vectors where semantically similar inputs are near each other in vector space. Embeddings power semantic search and retrieval-augmented generation scenarios.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["embeddings"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "A speech synthesis model converts text to audio, not text to semantic vectors.", "2": "Reinforcement learning tunes behavior through rewards; it does not by itself produce semantic text embeddings.", "3": "A rule-based parser applies grammar rules and does not create learned numeric vectors."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-015", "question": "Which parameter limits how long a model's generated response can be?", "options": ["Max tokens", "Temperature", "Top-p", "Frequency penalty"], "correctAnswer": 0, "explanation": "The max tokens setting caps the number of tokens the model can generate in its response, controlling output length and cost. Temperature and top-p instead influence randomness, while frequency penalty discourages repetition.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["model-parameters"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Temperature affects randomness, not the maximum length of output.", "2": "Top-p limits the probability mass sampled from, affecting diversity rather than length.", "3": "Frequency penalty reduces repeated tokens; it does not set a hard length cap."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-016", "question": "A model that can accept both text and images as input is best described as which kind of model?", "options": ["A multimodal model", "A unimodal text model", "A regression model", "A clustering model"], "correctAnswer": 0, "explanation": "A multimodal model can process more than one type of input, such as text and images together, and reason across them. These models power scenarios like describing an uploaded photo or answering questions about a chart.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["multimodal-models"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "A unimodal text model handles only text, not images.", "2": "A regression model predicts continuous numeric values, not multimodal content.", "3": "A clustering model groups similar data points and does not process images and text as a chat input."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-017", "question": "When selecting an AI model in Foundry, which factor is most important to match to your scenario?", "options": ["The model's capabilities, such as text, vision, or reasoning, relative to your task", "The alphabetical order of the model name", "The color of the model's icon in the catalog", "The number of letters in the model's version string"], "correctAnswer": 0, "explanation": "Choosing a model should be driven by whether its capabilities match the task, such as text generation, multimodal vision, embeddings, or reasoning, balanced against cost and performance. Cosmetic details like icons or naming are irrelevant.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["model-selection"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Alphabetical order has no bearing on whether a model fits the task.", "2": "Icon color is cosmetic and not a selection criterion.", "3": "The length of a version string is meaningless for model selection."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-018", "question": "Which workload is the best example of generative AI?", "options": ["Producing a draft marketing email from a short prompt", "Classifying an image as a cat or a dog", "Detecting fraud in a transaction stream", "Forecasting next month's sales from historical data"], "correctAnswer": 0, "explanation": "Generative AI creates new content such as text, images, or code. Drafting an email from a prompt is generative, whereas image classification, fraud detection, and forecasting are predictive or analytical workloads.", "exams": ["azure-ai-901"], "category": "ai-workloads", "topics": ["generative-ai-workload"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Classifying an image is a computer vision classification task, not content generation.", "2": "Fraud detection is anomaly detection or classification, not generative AI.", "3": "Sales forecasting is a predictive regression task, not generative content creation."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-019", "question": "What best describes an agentic AI workload?", "options": ["An AI solution that can plan steps and call tools or actions to accomplish a goal", "A static report that summarizes last year's data", "A spreadsheet macro that copies cells", "A manually written FAQ page"], "correctAnswer": 0, "explanation": "An AI agent uses a model to reason about a goal, decide on steps, and invoke tools or functions to carry out tasks. This goes beyond a single response by orchestrating actions toward an objective.", "exams": ["azure-ai-901"], "category": "ai-workloads", "topics": ["agentic-ai-workload"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "A static report does not plan or take actions; it is fixed output.", "2": "A spreadsheet macro follows fixed steps without AI reasoning.", "3": "A manually written FAQ involves no autonomous reasoning or tool use."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-020", "question": "Identifying whether a customer review expresses positive or negative feeling is an example of which text analysis technique?", "options": ["Sentiment analysis", "Keyword extraction", "Entity detection", "Language detection"], "correctAnswer": 0, "explanation": "Sentiment analysis evaluates text to determine whether the expressed opinion is positive, negative, neutral, or mixed. It is commonly used to gauge customer satisfaction from reviews and social posts.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["sentiment-analysis"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Keyword extraction pulls out key phrases, not the emotional tone.", "2": "Entity detection identifies named items like people or places, not sentiment.", "3": "Language detection identifies which language the text is written in, not its sentiment."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-021", "question": "Extracting the most important phrases that summarize what a document is about is known as which technique?", "options": ["Key phrase extraction", "Sentiment analysis", "Speech synthesis", "Translation"], "correctAnswer": 0, "explanation": "Key phrase extraction identifies the main concepts and important terms in a body of text. It helps quickly understand the gist of documents without reading them in full.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["key-phrase-extraction"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Sentiment analysis measures emotional tone, not the main phrases.", "2": "Speech synthesis converts text to audio, not extracting key phrases.", "3": "Translation converts text between languages, not summarizing key concepts."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-022", "question": "Recognizing that 'Seattle' is a location and 'Microsoft' is an organization within a sentence is an example of which technique?", "options": ["Named entity recognition", "Sentiment analysis", "Summarization", "Optical character recognition"], "correctAnswer": 0, "explanation": "Named entity recognition (NER) identifies and categorizes entities such as people, places, organizations, dates, and quantities in text. It is a core capability of Azure AI Language.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["entity-recognition"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Sentiment analysis measures opinion polarity, not entity categories.", "2": "Summarization condenses content, it does not label entities.", "3": "Optical character recognition reads text from images, not categorizing entities."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-023", "question": "Condensing a long article into a few sentences that capture the main points is which text analysis capability?", "options": ["Summarization", "Entity linking", "Language detection", "Translation"], "correctAnswer": 0, "explanation": "Summarization produces a shorter version of text that retains the essential information. Azure AI Language offers extractive and abstractive summarization for documents and conversations.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["summarization"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Entity linking connects entities to a knowledge base; it does not shorten text.", "2": "Language detection identifies the language used, not a summary.", "3": "Translation changes the language, it does not condense the content."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-024", "question": "Which Azure service provides natural language processing features such as sentiment analysis, entity recognition, and summarization?", "options": ["Azure AI Language", "Azure AI Vision", "Azure Cosmos DB", "Azure Virtual Machines"], "correctAnswer": 0, "explanation": "Azure AI Language is the service that delivers text analytics capabilities including sentiment analysis, key phrase extraction, named entity recognition, language detection, and summarization. It is a core part of Azure AI services.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["azure-ai-language"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Azure AI Vision processes images, not text analytics.", "2": "Azure Cosmos DB is a NoSQL database, not a language service.", "3": "Azure Virtual Machines provide compute, not NLP features."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-025", "question": "Converting written text into spoken audio is best described as which capability?", "options": ["Speech synthesis (text to speech)", "Speech recognition (speech to text)", "Sentiment analysis", "Translation"], "correctAnswer": 0, "explanation": "Speech synthesis, or text to speech, generates natural-sounding spoken audio from written text. Azure AI Speech offers many neural voices for this purpose.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["speech-synthesis"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Speech recognition does the reverse, turning audio into text.", "2": "Sentiment analysis evaluates emotional tone in text, not audio generation.", "3": "Translation converts between languages, not text into audio."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-026", "question": "Transcribing a recorded meeting into written text is an example of which capability?", "options": ["Speech recognition (speech to text)", "Speech synthesis (text to speech)", "Image classification", "Key phrase extraction"], "correctAnswer": 0, "explanation": "Speech recognition, or speech to text, converts spoken audio into a written transcript. It enables transcription, captioning, and voice-driven applications.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["speech-recognition"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Speech synthesis produces audio from text, the opposite direction.", "2": "Image classification labels images, unrelated to audio transcription.", "3": "Key phrase extraction works on text, not converting audio to text."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-028", "question": "Detecting where objects are located in an image and drawing bounding boxes around them is which computer vision task?", "options": ["Object detection", "Image classification", "Sentiment analysis", "Speech recognition"], "correctAnswer": 0, "explanation": "Object detection identifies the presence and location of multiple objects in an image, returning bounding box coordinates and labels for each. Image classification, by contrast, assigns a single label to the whole image.", "exams": ["azure-ai-901"], "category": "computer-vision", "topics": ["object-detection"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Image classification labels the whole image, without locating individual objects.", "2": "Sentiment analysis is a text technique, unrelated to images.", "3": "Speech recognition processes audio, not images."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-029", "question": "Assigning a single category label such as 'beach' or 'mountain' to an entire photo is which computer vision task?", "options": ["Image classification", "Object detection", "Optical character recognition", "Speech synthesis"], "correctAnswer": 0, "explanation": "Image classification assigns one or more category labels describing the overall content of an image. Object detection differs by locating and labeling individual objects within the image.", "exams": ["azure-ai-901"], "category": "computer-vision", "topics": ["image-classification"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Object detection locates multiple objects, rather than labeling the whole image once.", "2": "Optical character recognition reads text from images, not classifying scenes.", "3": "Speech synthesis produces audio and is unrelated to image labeling."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-030", "question": "Reading printed or handwritten text from a scanned receipt is enabled by which computer vision capability?", "options": ["Optical character recognition (OCR)", "Image classification", "Object detection", "Sentiment analysis"], "correctAnswer": 0, "explanation": "Optical character recognition (OCR) detects and extracts text from images and documents, including printed and handwritten content. Azure AI Vision provides OCR through its Read capability.", "exams": ["azure-ai-901"], "category": "computer-vision", "topics": ["ocr"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Image classification assigns scene labels, not reading text.", "2": "Object detection locates objects, not extracting text characters.", "3": "Sentiment analysis evaluates text tone and is not a vision capability."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-031", "question": "Which Azure service provides computer vision capabilities such as image analysis, OCR, and object detection?", "options": ["Azure AI Vision", "Azure AI Language", "Azure AI Speech", "Azure Functions"], "correctAnswer": 0, "explanation": "Azure AI Vision provides image analysis, optical character recognition, object detection, and image captioning. It is the computer vision service within Azure AI services.", "exams": ["azure-ai-901"], "category": "computer-vision", "topics": ["azure-ai-vision"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Azure AI Language handles text, not images.", "2": "Azure AI Speech handles audio, not images.", "3": "Azure Functions runs serverless code; it is not a vision service."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-032", "question": "Creating a brand-new image from a text description such as 'a red bicycle on a beach at sunset' uses which type of model?", "options": ["An image-generation model", "An object-detection model", "An OCR model", "A regression model"], "correctAnswer": 0, "explanation": "Image-generation models produce new images from text prompts. This is a generative AI computer vision capability, distinct from analyzing or classifying existing images.", "exams": ["azure-ai-901"], "category": "computer-vision", "topics": ["image-generation"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Object detection locates objects in existing images; it does not create new images.", "2": "OCR reads text from images and cannot generate images.", "3": "A regression model predicts numeric values, not images."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-033", "question": "Extracting field values such as invoice number, date, and total from a scanned invoice is best handled by which capability?", "options": ["Information extraction from documents", "Speech synthesis", "Image classification", "Sentiment analysis"], "correctAnswer": 0, "explanation": "Extracting structured fields from documents and forms is an information extraction task. In Foundry, Azure Content Understanding extracts data from documents, images, audio, and video.", "exams": ["azure-ai-901"], "category": "information-extraction", "topics": ["document-extraction"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Speech synthesis produces audio, not extracting document fields.", "2": "Image classification labels whole images, not pulling specific field values.", "3": "Sentiment analysis measures tone in text, not extracting structured data."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-034", "question": "Which Foundry capability is designed to extract information from documents, images, audio, and video in a unified way?", "options": ["Azure Content Understanding", "Azure Key Vault", "Azure Monitor", "Azure Load Balancer"], "correctAnswer": 0, "explanation": "Azure Content Understanding in Foundry Tools extracts structured information from multiple content types including documents, forms, images, audio, and video. It is the primary information extraction capability assessed on AI-901.", "exams": ["azure-ai-901"], "category": "information-extraction", "topics": ["content-understanding"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Azure Key Vault stores secrets; it does not extract content.", "2": "Azure Monitor collects telemetry, not extracting information from files.", "3": "Azure Load Balancer distributes network traffic; it has no extraction role."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-035", "question": "In a chat application, what is the purpose of a system prompt (system message)?", "options": ["To set the model's role, behavior, and constraints before user input is processed", "To store the application's connection string", "To display error logs to the end user", "To increase the GPU memory available to the model"], "correctAnswer": 0, "explanation": "A system prompt instructs the model on its persona, tone, scope, and rules, guiding how it responds to user messages. Well-crafted system messages are key to reliable, on-brand generative AI behavior.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["system-prompt"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Connection strings are configuration, not part of a system prompt's purpose.", "2": "System prompts guide model behavior; they are not for displaying error logs.", "3": "Prompts do not allocate hardware resources like GPU memory."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-036", "question": "Providing a few example input-output pairs inside a prompt to guide the model is known as what?", "options": ["Few-shot prompting", "Fine-tuning", "Quantization", "Tokenization"], "correctAnswer": 0, "explanation": "Few-shot prompting includes a small number of examples in the prompt so the model can infer the desired pattern without retraining. Zero-shot prompting provides no examples, while fine-tuning actually updates model weights.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["prompt-engineering"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Fine-tuning retrains the model on data; it is not adding examples within a prompt.", "2": "Quantization reduces model precision for efficiency, unrelated to prompting style.", "3": "Tokenization splits text into tokens; it is not a prompting technique."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-037", "question": "What is the main benefit of grounding a generative model with your own data using retrieval-augmented generation (RAG)?", "options": ["It lets the model answer using your specific, up-to-date information instead of only its training data", "It permanently changes the model's internal weights", "It removes the need for any prompt", "It guarantees the model never makes mistakes"], "correctAnswer": 0, "explanation": "RAG retrieves relevant content from your data sources and adds it to the prompt so the model can ground its answers in that information. This improves accuracy and relevance without modifying the base model's weights.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["rag-grounding"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "RAG does not change model weights; that is fine-tuning.", "2": "RAG still relies on a prompt, into which retrieved data is inserted.", "3": "No technique guarantees a model never errs; RAG only reduces hallucination risk."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-038", "question": "In Foundry, after selecting a model from the catalog, what must you do before an application can send requests to it?", "options": ["Deploy the model to create an endpoint", "Convert the model to a virtual machine image", "Email Microsoft support for activation", "Print the model card and scan it"], "correctAnswer": 0, "explanation": "In Foundry you deploy a chosen model, which provisions an endpoint and credentials that applications use to call it. Without a deployment there is no endpoint to send inference requests to.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["model-deployment"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Models are deployed as managed endpoints, not converted to VM images by you.", "2": "No support email is required to activate a catalog model.", "3": "Printing or scanning a model card has no effect on availability."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-039", "question": "Which tool lets you interactively test prompts against a deployed model directly in the Foundry portal?", "options": ["The chat playground", "Azure Resource Manager templates", "The billing dashboard", "The network security group editor"], "correctAnswer": 0, "explanation": "The chat playground in Foundry provides an interactive interface to test prompts, adjust parameters like temperature, and view responses before writing code. It is the fastest way to experiment with a deployed model.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["foundry-playground"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "ARM templates define infrastructure as code; they are not for testing prompts.", "2": "The billing dashboard shows costs, not prompt testing.", "3": "Network security group editors configure firewall rules, unrelated to prompts."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-040", "question": "What does the Foundry SDK primarily enable a developer to do?", "options": ["Write code that connects to and calls deployed models and services in Foundry", "Manually label training images in a browser", "Replace the need for any Azure subscription", "Render 3D graphics for games"], "correctAnswer": 0, "explanation": "The Foundry SDK lets developers programmatically connect to Foundry projects, call deployed models, and build client applications such as chat clients and agents. It abstracts the API calls behind language-specific libraries.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["foundry-sdk"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Image labeling is a data-prep task, not the core purpose of the SDK.", "2": "The SDK still requires an Azure subscription to access resources.", "3": "The SDK is for AI app development, not 3D game rendering."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-041", "question": "Which language's coding syntax does the AI-901 study guide expect candidates to be familiar with?", "options": ["Python", "COBOL", "Assembly", "Fortran"], "correctAnswer": 0, "explanation": "The AI-901 audience profile states candidates should know Python coding syntax and programming techniques, since Foundry SDK examples are shown in Python. Familiarity with Azure resources is also expected.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["python-prerequisite"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "COBOL is a legacy business language not referenced by the study guide.", "2": "Assembly is low-level programming not expected for AI fundamentals.", "3": "Fortran is a scientific computing language not part of the prerequisites."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-042", "question": "What distinguishes an AI agent from a single chat completion call?", "options": ["An agent can use tools, follow multi-step instructions, and act toward a goal", "An agent can only return a single fixed sentence", "An agent cannot use any model", "An agent runs only on a local laptop with no cloud"], "correctAnswer": 0, "explanation": "An agent combines a model with instructions, tools, and the ability to take actions across multiple steps to accomplish a goal. A single chat completion returns one response without orchestrating tool calls or multi-step reasoning.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["agents"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Agents are not limited to one fixed sentence; they reason and act over many steps.", "2": "Agents are built on top of a model, so they do use models.", "3": "Agents run in the cloud through Foundry, not exclusively on a local laptop."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-043", "question": "In Foundry, what are tools (also called actions or functions) in the context of an agent?", "options": ["Capabilities the agent can invoke, such as calling an API or searching data, to complete tasks", "Physical hardware sensors attached to the server", "Email templates sent to administrators", "Static images stored in blob storage"], "correctAnswer": 0, "explanation": "Tools give an agent capabilities beyond text generation, such as calling external APIs, querying data, or running code. The model decides when to invoke a tool to gather information or perform an action toward the goal.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["agent-tools"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Tools are software capabilities the agent calls, not physical sensors.", "2": "Email templates are unrelated to the concept of agent tools.", "3": "Static blob images are not the actionable tools an agent invokes."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-044", "question": "A developer wants to build a lightweight chat client that talks to a model deployed in Foundry. Which approach aligns with the AI-901 skills?", "options": ["Use the Foundry SDK to connect to the deployment and send chat messages", "Rewrite the model from scratch in C++", "Train a new foundation model on a single laptop", "Avoid using any code and rely on manual copy-paste only"], "correctAnswer": 0, "explanation": "AI-901 expects candidates to build lightweight client applications using the Foundry SDK to call a deployed model. This is far simpler than training models and is the recommended path for entry-level developers.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["chat-client"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Rewriting a foundation model in C++ is unnecessary and far beyond fundamentals scope.", "2": "Training a foundation model on a laptop is infeasible and not the intended approach.", "3": "Manual copy-paste is not building a client application."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-045", "question": "What is a Foundry project used for?", "options": ["To organize the resources, deployments, and connections for an AI solution", "To store unrelated personal photos", "To replace the Azure portal entirely", "To bill customers for Office licenses"], "correctAnswer": 0, "explanation": "A Foundry project is a workspace that groups model deployments, connected resources, data, and tools for building an AI solution. It gives developers a single place to manage everything an application needs.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["foundry-project"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Foundry projects organize AI resources, not personal photo storage.", "2": "A project does not replace the Azure portal; it is a workspace within Azure.", "3": "Billing for Office licenses is unrelated to Foundry projects."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-046", "question": "Which prompt would most likely produce reliable, focused output from a generative model?", "options": ["A clear, specific prompt that states the task, desired format, and any constraints", "A single vague word with no context", "A prompt written in random characters", "An empty prompt"], "correctAnswer": 0, "explanation": "Effective prompts are clear and specific, describing the task, expected format, and constraints. Vague or empty prompts give the model little to work with, producing unfocused or unpredictable results.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["prompt-engineering"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "A single vague word lacks the detail a model needs for focused output.", "2": "Random characters give the model no meaningful instruction.", "3": "An empty prompt provides no task at all."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-047", "question": "What is a hallucination in the context of generative AI?", "options": ["When a model produces confident output that is factually incorrect or fabricated", "When a model refuses to respond entirely", "When the network connection times out", "When the GPU overheats during inference"], "correctAnswer": 0, "explanation": "A hallucination is when a generative model produces plausible-sounding but false or fabricated information. Grounding the model with reliable data through techniques like RAG helps reduce hallucinations.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["hallucination"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "A refusal to respond is not a hallucination; hallucination is incorrect generated content.", "2": "A network timeout is an infrastructure issue, not a hallucination.", "3": "GPU overheating is a hardware problem, unrelated to hallucinated output."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-048", "question": "Which statement about Azure AI services is correct?", "options": ["They are prebuilt AI capabilities you can call through APIs without training your own models", "They require you to build and train every model from raw data first", "They run only on on-premises hardware", "They are limited to a single language"], "correctAnswer": 0, "explanation": "Azure AI services provide ready-to-use AI capabilities such as vision, language, and speech that developers consume through APIs and SDKs. They remove the need to build and train models from scratch for common tasks.", "exams": ["azure-ai-901"], "category": "ai-concepts", "topics": ["azure-ai-services"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "The whole point of Azure AI services is that prebuilt models exist, so you do not train from raw data.", "2": "These services are cloud-based, not limited to on-premises hardware.", "3": "Azure AI services support many languages, not just one."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-049", "question": "Translating a sentence from English to Japanese is an example of which NLP capability?", "options": ["Machine translation", "Sentiment analysis", "Object detection", "Optical character recognition"], "correctAnswer": 0, "explanation": "Machine translation converts text or speech from one language to another. Azure provides text translation through Azure Translator (now part of Foundry Tools, formerly Azure AI Translator) and speech translation through Azure AI Speech.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["translation"], "difficulty": "easy", "lastUpdated": "2026-06-23", "wrongExplanations": {"1": "Sentiment analysis measures emotional tone, not language conversion.", "2": "Object detection is a vision task, unrelated to language translation.", "3": "OCR reads text from images; it does not translate between languages."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-050", "question": "A multimodal model in Foundry receives a photo of a whiteboard and a question about its contents, then answers. This demonstrates which capability?", "options": ["Interpreting visual input in a prompt", "Generating a brand-new image", "Synthesizing speech from text", "Detecting fraud in transactions"], "correctAnswer": 0, "explanation": "When a multimodal model takes an image plus a text question and reasons about the image content, it is interpreting visual input within a prompt. AI-901 includes interpreting visual input by using a deployed multimodal model.", "exams": ["azure-ai-901"], "category": "computer-vision", "topics": ["multimodal-vision"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Generating a new image is the reverse direction from interpreting an existing one.", "2": "Speech synthesis produces audio, not image interpretation.", "3": "Fraud detection is an analytical task unrelated to interpreting images."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-051", "question": "Which scenario is the best fit for an image-generation model?", "options": ["Creating concept artwork for a product from a text description", "Reading the serial number printed on a device", "Counting how many cars appear in a parking-lot photo", "Transcribing a podcast episode"], "correctAnswer": 0, "explanation": "Image-generation models create original images from text prompts, making them ideal for producing concept art or marketing visuals. The other scenarios involve reading, counting, or transcribing existing content, which are analytical tasks.", "exams": ["azure-ai-901"], "category": "computer-vision", "topics": ["image-generation"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Reading a serial number is OCR, not image generation.", "2": "Counting cars is object detection, an analytical task.", "3": "Transcribing a podcast is speech to text, unrelated to image generation."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-052", "question": "Using Content Understanding to pull the spoken topics and key moments out of a recorded video is an example of extracting information from what?", "options": ["Audio and video content", "Relational database tables", "Network packet captures", "Source code repositories"], "correctAnswer": 0, "explanation": "Azure Content Understanding can extract information from audio and video, including transcripts, topics, and key moments. AI-901 covers extracting information from text, images, audio, and video.", "exams": ["azure-ai-901"], "category": "information-extraction", "topics": ["audio-video-extraction"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Relational tables are queried with SQL, not extracted by Content Understanding.", "2": "Network packet analysis is a security task, not content understanding.", "3": "Source code is parsed by developer tools, not by media content extraction."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-053", "question": "Which capability would best extract handwritten notes and key fields from a stack of scanned forms?", "options": ["Content Understanding document extraction", "Speech recognition", "Image generation", "Sentiment analysis"], "correctAnswer": 0, "explanation": "Extracting fields and text, including handwriting, from scanned forms is a document information extraction task handled by Azure Content Understanding in Foundry. It returns structured data from documents and images.", "exams": ["azure-ai-901"], "category": "information-extraction", "topics": ["document-extraction"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Speech recognition processes audio, not scanned forms.", "2": "Image generation creates new images; it does not read forms.", "3": "Sentiment analysis measures text tone, not extracting form fields."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-054", "question": "What is the AI-901 exam fee in the United States?", "options": ["$99 USD", "$165 USD", "$300 USD", "Free"], "correctAnswer": 0, "explanation": "Microsoft fundamentals exams such as AI-901 are priced at $99 USD in the United States, though pricing varies by country and excludes taxes. Role-based exams typically cost more.", "exams": ["azure-ai-901"], "category": "exam-logistics", "topics": ["exam-fee"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "$165 is closer to a role-based associate exam price, not the fundamentals fee.", "2": "$300 exceeds the fundamentals price; AI-901 is $99.", "3": "AI-901 is not free; the fee is $99 USD in the US."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-055", "question": "What passing score is required on the AI-901 exam?", "options": ["700 out of 1000", "500 out of 1000", "850 out of 1000", "65 out of 100"], "correctAnswer": 0, "explanation": "Microsoft exams, including AI-901, require a score of 700 or greater on a scale of 1 to 1000 to pass. The scaled score is not a simple percentage of correct answers.", "exams": ["azure-ai-901"], "category": "exam-logistics", "topics": ["passing-score"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "500 is below the required passing threshold of 700.", "2": "850 is higher than required; the pass mark is 700.", "3": "The score is on a 1000-point scale, not a 100-point percentage."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-056", "question": "Who administers and delivers the AI-901 exam?", "options": ["Microsoft, with delivery through Pearson VUE", "Oracle University", "CompTIA testing centers only", "Amazon Web Services"], "correctAnswer": 0, "explanation": "AI-901 is a Microsoft certification exam delivered through Pearson VUE, online or at a test center. Microsoft owns the exam content while Pearson VUE handles scheduling and proctoring.", "exams": ["azure-ai-901"], "category": "exam-logistics", "topics": ["exam-provider"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Oracle University runs Oracle exams, not Microsoft's AI-901.", "2": "CompTIA runs its own certifications, not Microsoft Azure exams.", "3": "AWS administers its own certifications, not Microsoft's."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-057", "question": "How long is the Microsoft Certified: Azure AI Fundamentals certification valid after passing AI-901?", "options": ["It does not expire because it is a fundamentals certification", "12 months, then it must be retaken", "24 months, then it must be repurchased", "6 months only"], "correctAnswer": 0, "explanation": "Microsoft fundamentals certifications, including Azure AI Fundamentals, do not expire. Only role-based associate, expert, and specialty certifications require annual renewal.", "exams": ["azure-ai-901"], "category": "exam-logistics", "topics": ["certification-validity"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Annual renewal applies to role-based and specialty certs, not fundamentals.", "2": "There is no 24-month expiry for fundamentals certifications.", "3": "Fundamentals certifications do not expire after 6 months."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-058", "question": "Roughly how much of the AI-901 exam focuses on implementing AI solutions by using Microsoft Foundry?", "options": ["55 to 60 percent", "10 to 15 percent", "5 percent", "90 percent"], "correctAnswer": 0, "explanation": "The official skills-at-a-glance shows Implement AI solutions by using Microsoft Foundry at 55 to 60 percent, making it the larger domain. Identify AI concepts and responsibilities accounts for 40 to 45 percent.", "exams": ["azure-ai-901"], "category": "exam-logistics", "topics": ["skill-weights"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "10 to 15 percent understates the largest domain on the exam.", "2": "5 percent is far too low for the Foundry implementation domain.", "3": "90 percent overstates it; the Foundry domain is 55 to 60 percent."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-059", "question": "Which conceptual workload would you choose to automatically route incoming support tickets to the right department based on their text?", "options": ["Text classification using natural language processing", "Image generation", "Speech synthesis", "Optical character recognition"], "correctAnswer": 0, "explanation": "Routing tickets based on their wording is a text classification NLP task that assigns categories to text. Azure AI Language supports custom text classification for scenarios like this.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["text-classification"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Image generation creates pictures, not classifying text tickets.", "2": "Speech synthesis produces audio, not categorizing text.", "3": "OCR reads text from images; the tickets are already text needing classification."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-060", "question": "A company wants users to ask questions in plain language and get answers drawn from its internal knowledge base. Which approach fits best?", "options": ["A generative AI chat solution grounded on the company's documents", "A static printed manual", "An image-generation model", "A speaker-recognition system"], "correctAnswer": 0, "explanation": "A generative chat solution grounded on internal documents lets users ask natural-language questions and receive answers based on the company's own content. Grounding the model with the knowledge base improves accuracy and relevance.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["rag-grounding"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "A static printed manual cannot answer natural-language questions interactively.", "2": "Image generation creates pictures, not knowledge-base answers.", "3": "Speaker recognition identifies who is speaking, not answering content questions."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-061", "question": "What does fine-tuning a model involve?", "options": ["Further training a base model on additional examples to adapt it to a specific task", "Restarting the Foundry portal", "Lowering the screen brightness during inference", "Deleting the model from the catalog"], "correctAnswer": 0, "explanation": "Fine-tuning continues training a pretrained model on task-specific examples so it performs better on that task or style. It changes the model's weights, unlike prompting techniques that leave the base model unchanged.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["fine-tuning"], "difficulty": "hard", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Restarting the portal has nothing to do with adapting a model.", "2": "Screen brightness is unrelated to model training.", "3": "Deleting a model removes it; fine-tuning instead specializes it."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-062", "question": "Which of these is the clearest example of where the privacy and security principle must be applied?", "options": ["Ensuring that personal health data sent to a model is encrypted and not exposed", "Choosing a brighter color theme for the app", "Adding more emojis to chatbot replies", "Renaming the deployment to a shorter name"], "correctAnswer": 0, "explanation": "Protecting sensitive personal data, such as health information, with encryption and access controls is a direct application of the privacy and security principle. The other options are cosmetic and unrelated to responsible AI.", "exams": ["azure-ai-901"], "category": "responsible-ai", "topics": ["privacy-security"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "A color theme is a UI choice, not a privacy or security concern.", "2": "Adding emojis does not relate to protecting data.", "3": "Renaming a deployment has no impact on data privacy."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-063", "question": "Which scenario best matches a computer vision workload?", "options": ["Identifying defective parts on a production line from camera images", "Translating a document into French", "Summarizing a news article", "Converting a paragraph into speech"], "correctAnswer": 0, "explanation": "Detecting defects from camera images is a computer vision task that analyzes visual data. Translation, summarization, and text to speech are language and speech workloads, not vision.", "exams": ["azure-ai-901"], "category": "computer-vision", "topics": ["vision-workload"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Translating a document is an NLP task, not computer vision.", "2": "Summarizing an article is a text analysis task.", "3": "Converting text to speech is a speech synthesis task."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-065", "question": "Which statement about choosing between a smaller and a larger language model is most accurate?", "options": ["Smaller models can be cheaper and faster, while larger models may handle more complex reasoning", "Larger models are always free and faster", "Smaller models can never answer any question", "Model size has no effect on cost or latency"], "correctAnswer": 0, "explanation": "Model selection involves trade-offs: smaller models often cost less and respond faster, while larger models may offer stronger reasoning at higher cost and latency. Matching the model to the task and budget is part of model selection on AI-901.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["model-selection"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Larger models are usually more expensive and not necessarily faster.", "2": "Smaller models can answer many questions; they are just less capable on complex tasks.", "3": "Model size clearly affects cost and latency."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-066", "question": "Which Azure AI Language feature would identify the language a piece of text is written in?", "options": ["Language detection", "Sentiment analysis", "Key phrase extraction", "Summarization"], "correctAnswer": 0, "explanation": "Language detection determines which natural language a text is written in and returns a confidence score. It is useful for routing multilingual content to the right processing pipeline.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["language-detection"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Sentiment analysis measures tone, not which language is used.", "2": "Key phrase extraction pulls main phrases, not detecting the language.", "3": "Summarization condenses content, it does not identify the language."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-067", "question": "An app needs to convert a customer's spoken request into text and then have a model respond aloud. Which two capabilities are combined?", "options": ["Speech to text and text to speech", "Object detection and image classification", "OCR and translation", "Embeddings and clustering"], "correctAnswer": 0, "explanation": "Capturing a spoken request requires speech to text, and responding aloud requires text to speech. Together these enable a voice-driven conversational experience, often paired with a multimodal model in Foundry.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["speech-pipeline"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Object detection and image classification are vision tasks, not speech.", "2": "OCR and translation handle text in images and language conversion, not voice interaction.", "3": "Embeddings and clustering are analytical techniques, not a speech pipeline."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-068", "question": "Which is a valid reason to deploy an AI model close to where its data resides or in a specific region?", "options": ["To meet data residency, compliance, or latency requirements", "To make the model larger automatically", "To remove the need for a prompt", "To disable responsible AI checks"], "correctAnswer": 0, "explanation": "Choosing a deployment region can address data residency rules, regulatory compliance, and latency for end users. Deployment configuration is part of identifying appropriate model deployment options on AI-901.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["deployment-options"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Region choice does not change a model's size.", "2": "A prompt is still required regardless of region.", "3": "Region selection does not disable responsible AI safeguards."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-069", "question": "What best describes the difference between extractive and abstractive summarization?", "options": ["Extractive selects key sentences from the source, while abstractive generates new wording", "Extractive translates text, while abstractive detects sentiment", "Extractive creates images, while abstractive creates audio", "There is no difference between them"], "correctAnswer": 0, "explanation": "Extractive summarization pulls the most important existing sentences from the text, whereas abstractive summarization generates new phrasing that paraphrases the content. Azure AI Language offers both styles.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["summarization"], "difficulty": "hard", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Neither type translates text or detects sentiment; both summarize.", "2": "Summarization works on text, not creating images or audio.", "3": "They are genuinely different approaches to summarization."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-070", "question": "Which scenario best demonstrates an information extraction workload?", "options": ["Pulling vendor names and amounts out of thousands of PDF receipts automatically", "Generating a poem from a prompt", "Playing a synthesized voice greeting", "Brightening the colors in a photo"], "correctAnswer": 0, "explanation": "Automatically extracting structured fields like vendor names and amounts from documents is an information extraction workload, handled by Azure Content Understanding in Foundry. The other options are generative or editing tasks.", "exams": ["azure-ai-901"], "category": "information-extraction", "topics": ["document-extraction"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Generating a poem is a generative AI task, not extraction.", "2": "Playing a synthesized voice is speech synthesis, not extraction.", "3": "Brightening photo colors is image editing, not information extraction."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-071", "question": "When building an agent in Foundry, what does giving the agent clear instructions accomplish?", "options": ["It defines the agent's goal, behavior, and how it should use its tools", "It encrypts the network traffic", "It increases the Azure subscription quota", "It changes the billing currency"], "correctAnswer": 0, "explanation": "Instructions tell the agent what its objective is, how to behave, and when to use available tools. Clear instructions are essential for an agent to act reliably toward the intended goal.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["agent-instructions"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Instructions guide behavior; they do not encrypt traffic.", "2": "Agent instructions do not change subscription quotas.", "3": "Billing currency is account configuration, not an agent instruction."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-072", "question": "Which example best illustrates the inclusiveness principle in a deployed AI product?", "options": ["Adding voice control and screen-reader support so people with disabilities can use the app", "Limiting the app to one premium customer segment", "Hiding all documentation from users", "Storing data without any backup"], "correctAnswer": 0, "explanation": "Inclusiveness means designing AI so that everyone, including people with disabilities, can benefit. Adding accessibility features like voice control and screen-reader support directly supports this principle.", "exams": ["azure-ai-901"], "category": "responsible-ai", "topics": ["inclusiveness"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Limiting access to one segment is the opposite of inclusiveness.", "2": "Hiding documentation reduces transparency and accessibility.", "3": "Skipping backups is a reliability issue, not inclusiveness."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-073", "question": "Which describes a key risk of generative AI that responsible AI practices aim to reduce?", "options": ["Generating biased, harmful, or false content", "Running out of disk space on a laptop", "Slow internet connections", "Using too many browser tabs"], "correctAnswer": 0, "explanation": "Generative models can produce biased, harmful, or factually incorrect content, so responsible AI practices like content filtering, grounding, and human oversight are applied to mitigate these risks. The other options are unrelated infrastructure or user issues.", "exams": ["azure-ai-901"], "category": "responsible-ai", "topics": ["generative-ai-risks"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Disk space is a hardware concern, not a generative AI risk.", "2": "Slow internet is a connectivity issue, not an AI content risk.", "3": "Browser tab count is unrelated to responsible AI."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-074", "question": "In Foundry, what is the purpose of a connection within a project?", "options": ["To securely link the project to a resource or data source it needs", "To physically wire two servers together", "To change the model's temperature setting", "To create a new Azure tenant"], "correctAnswer": 0, "explanation": "A connection in a Foundry project securely links it to external resources or data, such as a storage account or another AI service, so the solution can use them. Connections centralize and protect credentials.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["foundry-connections"], "difficulty": "hard", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Connections are logical links to resources, not physical cabling.", "2": "Temperature is a model parameter, not what a connection sets.", "3": "Creating a tenant is an identity operation, not a project connection."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-075", "question": "Predicting next month's electricity demand from years of historical readings is which kind of machine learning task?", "options": ["Regression (predicting a numeric value)", "Generative content creation", "Optical character recognition", "Speech synthesis"], "correctAnswer": 0, "explanation": "Predicting a continuous numeric value such as future demand is a regression task in machine learning. It differs from classification, which predicts categories, and from generative tasks that create new content.", "exams": ["azure-ai-901"], "category": "ai-concepts", "topics": ["regression"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Generative content creation makes new media, not numeric forecasts.", "2": "OCR reads text from images, unrelated to demand prediction.", "3": "Speech synthesis creates audio, not numeric forecasts."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-076", "question": "Sorting emails into 'spam' or 'not spam' is which kind of machine learning task?", "options": ["Classification", "Regression", "Image generation", "Speech recognition"], "correctAnswer": 0, "explanation": "Assigning items to discrete categories such as spam or not spam is a classification task. Regression predicts numeric values, so it is not the right description here.", "exams": ["azure-ai-901"], "category": "ai-concepts", "topics": ["classification"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Regression predicts numbers, not discrete spam categories.", "2": "Image generation creates pictures, unrelated to email sorting.", "3": "Speech recognition converts audio to text, not classifying emails."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-077", "question": "Which describes the relationship between AI, machine learning, and generative AI?", "options": ["Machine learning is a subset of AI, and generative AI is a subset of machine learning", "They are three completely unrelated fields", "Generative AI contains all of AI and machine learning", "Machine learning is broader than AI"], "correctAnswer": 0, "explanation": "Artificial intelligence is the broadest field, machine learning is a subset of AI that learns from data, and generative AI is a subset of machine learning focused on creating new content. Understanding these nested relationships is foundational.", "exams": ["azure-ai-901"], "category": "ai-concepts", "topics": ["ai-ml-relationship"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "They are nested fields, not unrelated.", "2": "Generative AI is a subset, not a superset containing all of AI.", "3": "AI is broader than machine learning, not the reverse."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-078", "question": "A retailer wants an AI feature that recommends products by understanding the meaning of a shopper's search phrase, even with different wording. Which technique supports this?", "options": ["Semantic search using embeddings", "Optical character recognition", "Text to speech", "Object detection"], "correctAnswer": 0, "explanation": "Semantic search uses embeddings to match queries to results based on meaning rather than exact keywords, so different phrasings still find relevant products. This is a common application of embedding models.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["semantic-search"], "difficulty": "hard", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "OCR reads text from images, not matching meaning of queries.", "2": "Text to speech produces audio, not search relevance.", "3": "Object detection is a vision task, not semantic text matching."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-079", "question": "Which is the best example of using a deployed multimodal model to respond to spoken prompts?", "options": ["A voice assistant that hears a question, reasons over it, and speaks a helpful answer", "A batch job that resizes thousands of images", "A scheduled report that emails sales totals", "A script that renames files on a server"], "correctAnswer": 0, "explanation": "Responding to spoken prompts with a multimodal model means the app captures speech, the model reasons over it, and a spoken answer is returned. AI-901 includes responding to spoken prompts by using a deployed multimodal model.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["multimodal-speech"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Resizing images is a batch image operation, not responding to speech.", "2": "Emailing a sales report is automation, not multimodal speech.", "3": "Renaming files is a scripting task, unrelated to spoken prompts."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-080", "question": "Why might an organization add a human-in-the-loop review step to a generative AI workflow?", "options": ["To verify or approve AI output for accuracy and safety before it is used", "To make the model run faster", "To eliminate the need for any responsible AI principles", "To reduce the model to a single token"], "correctAnswer": 0, "explanation": "Human-in-the-loop review lets people check, correct, or approve AI-generated output before it is acted on, supporting accountability, reliability, and safety. It is a common safeguard for high-stakes generative AI use cases.", "exams": ["azure-ai-901"], "category": "responsible-ai", "topics": ["human-in-the-loop"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Human review adds a step and does not speed up the model.", "2": "It supports, rather than eliminates, responsible AI principles.", "3": "It has nothing to do with reducing output to a single token."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-081", "question": "Which task is best suited to optical character recognition rather than a generative model?", "options": ["Digitizing the printed text on a stack of old paper forms", "Writing a creative short story", "Holding a back-and-forth conversation", "Designing a new company logo from a description"], "correctAnswer": 0, "explanation": "OCR is purpose-built to detect and read existing text from images and documents, making it ideal for digitizing paper forms. Story writing, conversation, and logo design are generative tasks.", "exams": ["azure-ai-901"], "category": "computer-vision", "topics": ["ocr"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Writing a story is a generative language task, not OCR.", "2": "Holding a conversation is a chat task, not text extraction.", "3": "Designing a logo from a description is image generation, not OCR."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-083", "question": "Which factor would NOT typically influence which generative model you choose for a task?", "options": ["The favorite color of the developer", "Whether the task needs vision or only text", "The cost and latency of the model", "The quality of the model's reasoning"], "correctAnswer": 0, "explanation": "Model selection should be based on capabilities, cost, latency, and quality relative to the task. A developer's favorite color is irrelevant and should never drive a model choice.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["model-selection"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Whether the task needs vision is a real, important selection factor.", "2": "Cost and latency are legitimate model-selection considerations.", "3": "Reasoning quality is a key factor in choosing a model."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-084", "question": "A developer builds an app that takes a product photo and returns a written description of it. Which capability is at the core of this app?", "options": ["Image analysis or captioning by a vision-capable model", "Speech translation", "Regression forecasting", "Speaker verification"], "correctAnswer": 0, "explanation": "Turning an image into a written description is image analysis or captioning, performed by a vision-capable or multimodal model. It interprets visual content and outputs descriptive text.", "exams": ["azure-ai-901"], "category": "computer-vision", "topics": ["image-captioning"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Speech translation works on audio, not images.", "2": "Regression forecasting predicts numbers, not image descriptions.", "3": "Speaker verification identifies voices, not describing images."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-085", "question": "Which statement about Foundry Tools such as Azure Speech and Content Understanding is correct?", "options": ["They provide specialized AI capabilities you can build into Foundry applications", "They are only available as physical hardware appliances", "They replace the need for an Azure account", "They can only process data from the year 1990"], "correctAnswer": 0, "explanation": "Foundry Tools, including Azure Speech and Content Understanding, offer specialized AI capabilities like speech processing and information extraction that developers integrate into their Foundry solutions. They are cloud services consumed through the platform.", "exams": ["azure-ai-901"], "category": "information-extraction", "topics": ["foundry-tools"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "These are cloud services, not physical hardware appliances.", "2": "They still require an Azure account to use.", "3": "There is no such date limitation on the data they process."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-087", "question": "Which is a realistic example of an agentic AI solution built in Foundry?", "options": ["An assistant that checks a calendar tool and books a meeting based on a user request", "A static webpage with no interactivity", "A printed brochure", "A spreadsheet formula that adds two cells"], "correctAnswer": 0, "explanation": "An agent that interprets a request, calls a calendar tool, and books a meeting is acting toward a goal using tools, which is the essence of an agentic solution. The other options involve no autonomous reasoning or tool use.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["agents"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "A static webpage takes no actions toward a goal.", "2": "A printed brochure has no AI behavior.", "3": "A spreadsheet formula follows a fixed calculation, not agentic reasoning."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-088", "question": "Why is grounding especially important when a generative app answers questions about company policies?", "options": ["It ensures answers come from the actual policy documents rather than the model's guesses", "It makes the font larger", "It disables the model's safety filters", "It converts the answer into an image"], "correctAnswer": 0, "explanation": "Grounding ties the model's answers to authoritative source documents, so policy questions are answered from the real policies rather than potentially incorrect model assumptions. This reduces hallucinations and improves trust.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["rag-grounding"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Grounding affects answer sourcing, not font size.", "2": "Grounding does not disable safety filters.", "3": "Grounding does not convert text answers into images."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-089", "question": "Which scenario is the best example of extracting information from images using Content Understanding?", "options": ["Reading product labels and prices from shelf photos in a store", "Composing background music for a video", "Translating a webpage into Spanish", "Forecasting quarterly revenue"], "correctAnswer": 0, "explanation": "Reading labels and prices from shelf photos extracts structured information from images, which Content Understanding supports. Composing music, translating text, and forecasting revenue are different workloads entirely.", "exams": ["azure-ai-901"], "category": "information-extraction", "topics": ["image-extraction"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Composing music is a generative audio task, not image extraction.", "2": "Translating a webpage is an NLP task, not extracting from images.", "3": "Forecasting revenue is a predictive numeric task."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-090", "question": "What does it mean that AI-901 is currently in beta?", "options": ["The exam is newly released and its questions are being validated before final scoring", "The exam is free during this period", "The exam has no passing score", "The certification cannot be earned at all"], "correctAnswer": 0, "explanation": "A beta exam is newly launched while Microsoft validates question performance; scores may be reported after the beta period. Candidates can still take it and earn the certification once results are finalized.", "exams": ["azure-ai-901"], "category": "exam-logistics", "topics": ["beta-exam"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Beta status does not make the exam free; the standard fee still applies.", "2": "The passing score of 700 still applies to AI-901.", "3": "The certification can be earned; beta scoring is finalized after the period."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-091", "question": "Which describes the difference between a base model and a fine-tuned model?", "options": ["A base model is general purpose, while a fine-tuned model is adapted to a specific task or domain", "A base model cannot generate any text", "A fine-tuned model is always smaller in file size", "There is no functional difference"], "correctAnswer": 0, "explanation": "A base model is pretrained for broad, general use, while fine-tuning adapts it with additional task- or domain-specific training data. Fine-tuning can improve performance on specialized tasks but is not always necessary.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["fine-tuning"], "difficulty": "hard", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "A base model absolutely can generate text; that is its purpose.", "2": "Fine-tuning does not necessarily reduce file size.", "3": "There is a meaningful difference in specialization."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-092", "question": "An app must detect whether uploaded user images contain adult or violent content before publishing them. Which capability is the right choice?", "options": ["Azure AI Content Safety image moderation", "Text to speech", "Regression analysis", "Language detection"], "correctAnswer": 0, "explanation": "Azure AI Content Safety can analyze images and flag harmful categories such as adult or violent content, supporting safe publishing workflows. It is part of applying responsible AI safeguards to user-generated content.", "exams": ["azure-ai-901"], "category": "responsible-ai", "topics": ["content-safety"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Text to speech generates audio and cannot moderate images.", "2": "Regression analysis predicts numbers, not detecting harmful imagery.", "3": "Language detection identifies text language, not image content risks."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-093", "question": "Which is the most accurate description of how an agent decides to call a tool?", "options": ["The model reasons about the task and chooses to invoke a tool when it needs more information or an action", "Tools are always called in a fixed alphabetical order", "A human must manually trigger every tool call", "Tools are never used by agents"], "correctAnswer": 0, "explanation": "An agent's underlying model reasons about the goal and decides, based on the current state, when calling a tool will help it gather information or perform an action. This dynamic decision-making is what makes agents flexible.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["agent-tools"], "difficulty": "hard", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Tool calls are decided by reasoning, not a fixed alphabetical order.", "2": "Agents can call tools autonomously without a human triggering each one.", "3": "Tool use is a defining feature of agents, so they do use tools."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-094", "question": "Which is a correct statement about how generative AI relates to traditional predictive machine learning?", "options": ["Generative AI creates new content, while traditional ML often predicts a label or value", "Generative AI and predictive ML are identical", "Traditional ML can only generate images", "Generative AI cannot use any training data"], "correctAnswer": 0, "explanation": "Generative AI focuses on producing new content such as text or images, whereas traditional predictive machine learning typically outputs a category or numeric prediction. Both learn from data but serve different goals.", "exams": ["azure-ai-901"], "category": "ai-concepts", "topics": ["generative-vs-predictive"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "They are not identical; their purposes differ.", "2": "Traditional ML predicts labels or values; it is not limited to generating images.", "3": "Generative AI is trained on large amounts of data."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-095", "question": "A team wants to test how changing the system prompt affects a chatbot's tone before deploying code. Where should they do this most efficiently?", "options": ["In the Foundry chat playground", "By editing the Azure billing settings", "By resizing the virtual network", "By changing their laptop wallpaper"], "correctAnswer": 0, "explanation": "The Foundry playground lets teams adjust the system prompt and immediately observe how the chatbot's responses and tone change, without writing application code. This rapid iteration is exactly what the playground is for.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["foundry-playground"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Billing settings do not affect prompt behavior testing.", "2": "Resizing a virtual network is unrelated to prompt iteration.", "3": "Wallpaper has no effect on chatbot tone."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-096", "question": "Which scenario best fits using speech translation?", "options": ["A traveler speaks English and the app speaks the translated phrase in Spanish", "An app counts cars in a traffic video", "A model writes a marketing slogan", "A system extracts totals from invoices"], "correctAnswer": 0, "explanation": "Speech translation converts spoken words from one language to another, ideal for real-time travel or conversation scenarios. Counting cars, writing slogans, and extracting invoice totals are vision, generative, and extraction tasks respectively.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["speech-translation"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Counting cars in video is a computer vision task.", "2": "Writing a slogan is a generative language task, not translation.", "3": "Extracting invoice totals is information extraction, not speech translation."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-097", "question": "Why should a developer monitor token usage when running a generative AI application?", "options": ["Tokens affect both cost and whether the input fits within the context window", "Tokens determine the screen resolution", "Tokens set the keyboard language", "Tokens control the operating system version"], "correctAnswer": 0, "explanation": "Token usage drives cost, since billing is often per token, and it determines whether prompts and responses fit within the model's context window. Monitoring tokens helps manage both budget and behavior.", "exams": ["azure-ai-901"], "category": "generative-ai", "topics": ["tokens"], "difficulty": "hard", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Tokens have nothing to do with screen resolution.", "2": "Tokens do not set the keyboard language.", "3": "Tokens are unrelated to the operating system version."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-098", "question": "Which combination of capabilities would a customer-service voice bot most likely use?", "options": ["Speech to text, a generative model with grounding, and text to speech", "Only image generation", "Only OCR", "Only regression forecasting"], "correctAnswer": 0, "explanation": "A voice bot transcribes the caller with speech to text, generates a grounded answer with a model, and replies aloud with text to speech. Combining these capabilities creates a natural spoken support experience.", "exams": ["azure-ai-901"], "category": "generative-ai-apps", "topics": ["solution-design"], "difficulty": "hard", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Image generation alone cannot transcribe or speak to a caller.", "2": "OCR alone reads text from images and cannot run a voice conversation.", "3": "Regression forecasting predicts numbers and is not a voice bot capability."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-099", "question": "Which statement about the AI-901 exam format is correct?", "options": ["It is a multiple-choice exam delivered in about 45 minutes with roughly 40 to 60 questions", "It is an open-book essay exam lasting 8 hours", "It is a hands-on lab with no questions", "It is an oral interview with a Microsoft engineer"], "correctAnswer": 0, "explanation": "AI-901 is a multiple-choice fundamentals exam, typically around 45 minutes with roughly 40 to 60 questions. It does not include long essays, labs, or oral interviews.", "exams": ["azure-ai-901"], "category": "exam-logistics", "topics": ["exam-format"], "difficulty": "easy", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "It is not an 8-hour open-book essay exam.", "2": "There is no hands-on lab replacing the questions for AI-901.", "3": "It is not an oral interview."}, "source": "azure-ai-901"}, {"id": "azure-ai-901-100", "question": "A developer wants the simplest path to add text analysis, like sentiment, to an app using Foundry. Which approach matches the AI-901 expectations?", "options": ["Build a lightweight application that calls a Foundry text-analysis capability", "Train a new language model from scratch on a personal computer", "Manually read and label every document by hand", "Avoid Foundry and write the analysis in spreadsheet formulas"], "correctAnswer": 0, "explanation": "AI-901 expects candidates to build lightweight applications that use Foundry capabilities such as text analysis, rather than training models from scratch. Calling a ready-made capability is the efficient, recommended path.", "exams": ["azure-ai-901"], "category": "natural-language-processing", "topics": ["text-analysis-app"], "difficulty": "medium", "lastUpdated": "2026-05-24", "wrongExplanations": {"1": "Training a language model from scratch is impractical and out of scope for fundamentals.", "2": "Manual labeling defeats the purpose of automating text analysis.", "3": "Spreadsheet formulas cannot perform genuine sentiment analysis."}, "source": "azure-ai-901"}]};
